(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["image"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-dc-gen-post-training-diffusion-accel-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-1\">一 · 一个真实在线服务场景：队列尾部的 4 秒</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-2\">二 · 旧方案的主流形态：高维潜空间 + 多步采样 + 一次性 VAE 解码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-3\">三 · 为什么“只压步数”和“只加批”都不够</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-4\">四 · 旧方案在 Blackwell 档位上的具体错配</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-5\">五 · 旧栈的失败模式与容量规划的连锁反应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-6\">六 · 工程判断：瓶颈定位先于方案选型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-7\">七 · 压缩比不是免费旋钮：旧栈在在线服务里的失效边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-8\">八 · 请求形态：步数分布才是负载的第一坐标</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-9\">九 · 并发与批大小：压缩比与批大小是同一根显存杠杆的两端</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-10\">十 · SLO 与长尾：尾延迟由最重的那条请求定义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-11\">十一 · 负载塑造方案：分桶与压缩比的自洽</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-12\">十二 · 可核查的测量口径清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-13\">十三 · 失败模式与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-14\">十四 · 压缩比作为容量杠杆时的负载边界与测量口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-15\">十五 · 压缩潜变量如何改写算子形状</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-16\">十六 · 数据类型分层：FP16/BF16 到 FP8 再到 NVFP4</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-17\">十七 · 累加精度与误差传播</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-18\">十八 · Blackwell 特性在压缩潜空间上的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-19\">十九 · 精度与压缩叠加的容量核算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-20\">二十 · 失败模式与 kernel 级判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-21\">二十一 · 压缩潜空间的数值边界：低精度算子与误差叠加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-22\">二十二 · 显存账本的三层结构：权重、激活、KV</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-23\">二十三 · 分页与复用：把压缩潜变量当成可换出的页</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-24\">二十四 · 带宽瓶颈：HBM3e 容量与每步读写量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-25\">二十五 · 卸载与低精度叠加：压缩比之外的第二个旋钮</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-26\">二十六 · 压缩潜空间的显存账本：从张量形状到峰值预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-27\">二十七 · 分桶与批组装：压缩潜空间改变了批的粒度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-28\">二十八 · 连续批处理与 chunked prefill 在扩散采样里的对应物</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-29\">二十九 · 优先级、抢占与压缩比作为调度维度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-30\">三十 · 分离式预填/解码在扩散链路里的映射</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-31\">三十一 · 尾延迟的压法：从 P99 反推批与步的预算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-32\">三十二 · 压缩潜空间下的批调度边界：桶化、抢占与解码尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-33\">三十三 · 压缩潜空间如何改写并行切分的成本函数</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-34\">三十四 · EP 与 All-to-All：压缩改变的是专家负载而非链路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-35\">三十五 · PP 与 DP：流水气泡与副本冗余的重新定价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-36\">三十六 · NVLink 5、NVSwitch 与 NIXL：谁在什么时候成为瓶颈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-37\">三十七 · 通信瓶颈的判定与压缩比的联动标定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-38\">三十八 · 压缩潜空间下的并行拓扑：切分维度如何被压缩比改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-39\">三十九 · 精度塌陷：压缩误差与低精度叠加的失效链</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-40\">四十 · OOM：峰值显存的三处叠加点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-41\">四十一 · 批抖动与尾延迟：分桶边界上的排队失稳</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-42\">四十二 · 静默降级：没有报错的质量滑坡</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-43\">四十三 · 定位与回滚：把配置指纹做成可回退单元</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-44\">四十四 · 压缩比越界后的静默降级与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-45\">四十五 · 论文口径的空缺与自建标定的必要性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-46\">四十六 · 硬件档位与 batch／并发的交叉变量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-47\">四十七 · 指标定义：TTFT、TPOT 与扩散采样的错位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-48\">四十八 · 吞吐与功耗：两个容易被混用的口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-49\">四十九 · 哪些提升不可比：四类典型陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-50\">五十 · 可复现的标定流程与工程判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-51\">五十一 · 压缩比不是免费旋钮：口径边界与失效条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-52\">五十二 · 迁移到非图像模态：压缩器要重训，主干未必能冻</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-53\">五十三 · 迁移到非 DiT 主干：注意力序列缩短的收益不再线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-54\">五十四 · 与低精度叠加的边界：误差是相乘而非相加</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-55\">五十五 · 规模上限：压缩比的天花板由解码器感受野与主干容量共同决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-56\">五十六 · 不适用的场景与工程判断</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:584px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 584.1 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入服务队列，按分辨率与步数分桶，批调度器合并同桶请求以摊薄 Di…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">输入图像或初始噪声经压缩编码器映射到深度压缩潜空间，张量维度低于原始潜…</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">在压缩潜空间内执行扩散／流匹配采样，DiT 主干每步读取压缩潜变量并输…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">采样完成后，压缩解码器把最终潜变量一次性还原为像素图像，解码输入规模随…</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"502.1\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">结果写回响应队列，监控记录每步延迟、显存峰值与压缩比对应的质量指标。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-1\">一 · 一个真实在线服务场景：队列尾部的 4 秒</h3>\n<p>设想一个面向 C 端的产品图生成服务：入口网关把请求按 1024×1024 与 768×768 两个分辨率分桶，每桶再按采样步数（例如 28 步与 50 步两档）切子桶。GPU 侧跑的是 B200 单机八卡，DiT 主干以 FP8 权重加载，KV 式中间缓存按步复用。表面上看，单请求在空载时能压在 SLO 之内；但一旦并发爬升，调度器把同桶请求合并成批，问题立刻显形——批内每一条请求都要在潜空间里跑满几十步，每步都要把整块潜变量张量读进 SM、做一次全序列注意力、再写回显存。尾延迟不是被算力卡住，而是被潜空间张量的反复读写卡住：注意力矩阵随序列长度平方增长，中间缓存随批大小线性增长，显存带宽在每步之间被反复打满。运维看到的曲线是：平均延迟尚可，P99 端到端延迟在高峰期翻倍，而 GPU 利用率并没有跑满，说明瓶颈在数据搬运而非浮点吞吐。</p>\n<p>这就是本部分要交代的“问题现场”：在 DC-Gen 这类后训练潜空间压缩方案出现之前，推理栈面对扩散／流匹配模型的主流做法是什么，代价落在哪里，以及为什么这些做法在 Blackwell 档位上仍然不够。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-2\">二 · 旧方案的主流形态：高维潜空间 + 多步采样 + 一次性 VAE 解码</h3>\n<p>论文之前的推理栈基本沿三条主线组织。第一条是<strong>原始潜空间直跑</strong>：VAE 编码器把像素压到一个相对高维的潜空间（通道数与空间分辨率都保留相当规模），DiT 在这个潜空间上执行全部去噪步，最后 VAE 解码器一次性还原像素。第二条是<strong>步数侧加速</strong>：用更快的采样器、蒸馏或一致性类方法把步数从几十步压到几步，但每步的张量规模不变。第三条是<strong>批调度侧摊薄</strong>：连续批处理把同分辨率、同步数的请求合并，用批大小摊薄主干前向的固定开销。三条线各自有效，但都没有触碰潜空间本身的维度。</p>\n<p>代价可以写成一句话：每步的计算量与显存占用由潜空间张量的形状决定，而形状由原始 VAE 的压缩比固定死。设潜变量形状为 <span>C×H×W</span>，DiT 把空间维展平成序列后，注意力矩阵规模随 <span>(H·W)²</span> 增长，线性层张量随 <span>C·H·W</span> 增长，每步的中间缓存同样随这两项增长。步数侧加速只减少“跑多少步”，不减少“每步多贵”；批调度只把固定开销摊薄，不改变单请求的显存足迹。当并发上来、批大小被迫调大时，显存峰值先撞墙，调度器只能降批，吞吐随之掉下去——这正是上面那个服务场景里 P99 翻倍的机制来源。</p>\n<div class=\"formula\">$$\\text{每步代价}\\;\\propto\\;\\underbrace{(H\\!\\cdot\\!W)^2}_{\\text{注意力}}\\;+\\;\\underbrace{C\\!\\cdot\\!H\\!\\cdot\\!W}_{\\text{线性层与缓存}},\\qquad \\text{端到端}\\;\\approx\\;\\text{步数}\\times\\text{每步代价}+\\text{VAE 解码}$$</div>\n<p>具体到一个 1024×1024 请求：原始潜空间若按常见的 8 倍空间下采样，空间维是 128×128，展平后序列长度约一万六千；注意力矩阵是这一长度的平方量级，每步都要在显存里生成、读写、释放。批大小到 8 时，仅这一项的中间缓存就足以把单卡显存预算吃掉一大块，调度器不得不把批压回 4 甚至 2。这不是某个算子写得不好，而是潜空间维度本身把每步的显存带宽需求钉死在高位。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-3\">三 · 为什么“只压步数”和“只加批”都不够</h3>\n<p>步数侧加速的工程代价在于质量与通用性：蒸馏与一致性类方法需要额外的训练阶段或教师模型，且对采样器、引导尺度、分辨率切换敏感；服务侧一旦要支持多档分辨率与多档步数，维护多套蒸馏权重本身就是容量规划的负担。更关键的是，步数减半并不等于端到端延迟减半——VAE 解码是一次性的大张量还原，步数压缩后解码在端到端中的占比反而上升，尾延迟的天花板从采样段转移到解码段。</p>\n<p>批调度侧的天花板更直接：连续批处理把同桶请求合并，能摊薄主干的权重读取与固定开销，但显存峰值随批大小线性上升。压缩潜变量若仍以原始维度存放，批大小每加一档，中间缓存与注意力矩阵就同步膨胀；在 Blackwell 的显存预算下，这条路的边际收益很快被显存墙截断。工程上常见的补救是把中间缓存转 FP8 存放，但 FP8 只降低每元素的字节数，不改变元素个数——序列长度与通道数没变，注意力矩阵的规模没变。</p>\n<p>两条旧路线共同的盲点是：它们都把潜空间维度当成不可动的常量。而每步代价公式里，<span>(H·W)²</span> 与 <span>C·H·W</span> 恰恰是对维度最敏感的两项。这就是为什么非改不可——不是算子层面的微调，而是要把采样发生的空间本身换掉。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-4\">四 · 旧方案在 Blackwell 档位上的具体错配</h3>\n<p>Blackwell（SM100/SM103）给了 NVFP4/FP8 张量核心与更大的显存，但旧栈的低精度路径主要落在权重与激活上，潜空间张量仍以较高精度、原始维度在显存里来回搬运。这造成一种错配：张量核心的吞吐上去了，每步却仍在等显存带宽；tcgen05 与 TMEM 的异步流水能掩盖计算延迟，却掩盖不了注意力矩阵规模随序列长度平方增长带来的容量压力。换句话说，硬件把“算得快”这一侧补齐了，旧栈的瓶颈反而更集中在“搬得多、存得大”这一侧。</p>\n<p>一个具体的错配例子：把 DiT 权重压到 FP8、把激活也压到 FP8 之后，单步的浮点运算时间明显缩短，但每步仍需读写整块高维潜变量与其中间缓存；此时 SM 的利用率曲线出现“计算段短、搬运段长”的锯齿，批大小稍大就撞显存峰值。工程判断很直接：在 Blackwell 上继续沿旧路线优化，收益递减点在显存带宽与容量，而不在张量核心。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-5\">五 · 旧栈的失败模式与容量规划的连锁反应</h3>\n<p>旧栈在服务化下的失败模式有三类，且互相耦合。第一类是<strong>显存峰值越界</strong>：并发上升时调度器加批，中间缓存与注意力矩阵同步膨胀，触发降批或 OOM 重试，表现为 P99 抖动而非平均延迟恶化。第二类是<strong>解码段成为尾延迟主导</strong>：步数被压缩后，VAE 解码的一次性大张量还原在端到端中的占比上升，解码峰值显存与解码时间成为新的容量约束。第三类是<strong>多档分辨率下的碎片化</strong>：不同分辨率的潜空间形状不同，分桶后每桶的批调度窗口与显存足迹各异，容量规划只能按最坏桶预留，整体 GPU 利用率被拉低。</p>\n<p>这三类失败模式共同指向一个结论：容量规划的杠杆若只放在“步数”和“批大小”上，自由度很快耗尽。调度器在显存峰值越界时只有两个动作——降批或降精度——前者直接损失吞吐，后者在旧栈上只降低字节数、不降低元素个数，收益有限。要真正把尾延迟压回 SLO 之内，需要一个能同时缩小“每步张量规模”和“解码输入规模”的杠杆，而这正是把潜空间维度本身作为可调旋钮的思路所要解决的问题；其具体机制（后训练只训编解码器、冻结主干、压缩比与重建项权重 λ 的权衡）属于后续部分的内容，这里只交代它为何在旧栈的失败模式面前成为必要选项。</p>\n<table class=\"mini\"><thead><tr><th>旧栈做法</th><th>直接代价</th><th>服务侧表现</th></tr></thead><tbody><tr><td>原始高维潜空间直跑</td><td>每步注意力矩阵随序列长度平方增长，中间缓存随批线性增长</td><td>并发上升即撞显存峰值，被迫降批，吞吐下滑</td></tr><tr><td>步数侧加速（蒸馏/一致性类）</td><td>需额外训练阶段或多套权重，解码段占比上升</td><td>尾延迟天花板从采样段转移到 VAE 解码段</td></tr><tr><td>连续批处理摊薄</td><td>显存峰值随批大小线性上升，边际收益被显存墙截断</td><td>容量规划按最坏桶预留，GPU 利用率被拉低</td></tr><tr><td>中间缓存转 FP8</td><td>只降字节数不降元素个数，注意力规模不变</td><td>低精度收益有限，峰值显存仍越界</td></tr></tbody></table>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-6\">六 · 工程判断：瓶颈定位先于方案选型</h3>\n<p>把问题现场收束成一条可操作的判断：在 Blackwell 上做扩散推理服务，先测三件事——每步延迟里计算段与搬运段的比例、显存峰值随批大小的增长斜率、VAE 解码在端到端尾延迟中的占比。若搬运段主导且显存峰值斜率陡，说明瓶颈在潜空间张量规模，步数与批调度的优化空间已经不多；若解码占比随步数压缩而上升，说明解码输入规模需要同步下降。这两条测量结果共同决定是否需要把潜空间维度作为容量杠杆——DC-Gen 的后训练压缩方案正是在这个判断点上进入视野的，而它的具体训练配方与压缩比标定方法，留给后续部分展开。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-7\">七 · 压缩比不是免费旋钮：旧栈在在线服务里的失效边界</h3>\n<p>一个典型的在线图像生成服务里，请求按分辨率与步数分桶后合批，端到端尾延迟由三段拼成：压缩编码器一次前向、DiT 在潜空间里跑完既定步数、VAE 解码一次性还原像素。旧方案把这三段都压在原始高维潜空间上，于是每步 DiT 的注意力矩阵与线性层张量规模、以及解码输入规模，全部随原始潜变量维度线性甚至平方级放大。Blackwell 的 NVFP4/FP8 张量核心与大显存能压低单次矩阵乘的时间，却压不住张量本身的规模——步数乘以每步张量规模才是吞吐的分母。设单请求步数为 $S$、批大小为 $B$、每步注意力计算量近似正比于序列长度平方 $L^2$ 与通道数 $C$，则一批的总计算代价可写成 $T_{\\text{batch}} \\approx S \\cdot B \\cdot f(L^2, C)$，压缩潜空间同时缩小 $L$ 与 $C$，而单纯换低精度只改变 $f$ 的常数因子。</p>\n<p>失效条件集中在两处。其一是压缩比被当成免费加速旋钮：损失里重建项系数 $\\lambda$ 越小、压缩越深，$\\|\\mathcal{D}(\\mathcal{E}(x))-x\\|_2^2$ 的残差越容易在多次采样后被放大，细节丢失先出现在高频纹理与文字区域，而监控侧若只看端到端延迟不看质量指标，就会把质量下滑误判为容量收益。其二是主干未重训带来的分布偏移：压缩空间与原模型训练分布不一致时，采样轨迹可能偏离，表现为同种子下结果方差变大，这类不稳定不会体现在均值延迟上，却会拉高尾延迟的方差。两者叠加时，压缩潜变量再以 FP8/NVFP4 存放，低精度与压缩误差的叠加边界论文未给出，部署侧只能逐档标定。</p>\n<p>系统代价要按段拆开算。编码器是每请求一次的前向，压缩比提高会略微增加其开销，但相对 $S$ 步 DiT 可忽略；DiT 段是主战场，压缩后每步只读写压缩潜变量，KV 式中间缓存同步变小，显存峰值下降直接换来更大批大小或更低精度存放；解码段的一次性像素还原输入规模随压缩比下降，端到端尾延迟中解码占比随之改变，原本被解码拖住的长尾请求会前移到 DiT 段。工程判断是：把压缩比与 $\\lambda$ 作为容量规划的自由度逐档扫描，同时记录每步延迟、显存峰值与对应质量指标，显存峰值越界时优先降批大小或降精度，而不是继续加深压缩。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>压缩过深</td><td>高频细节与文字区域残差上升</td><td>质量指标下滑，需回退压缩档</td></tr><tr><td>主干分布偏移</td><td>同种子结果方差变大</td><td>尾延迟方差上升，SLO 难达标</td></tr><tr><td>低精度叠加压缩</td><td>显存峰值越界或数值异常</td><td>被迫降批，吞吐回吐</td></tr></tbody></table>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-8\">八 · 请求形态：步数分布才是负载的第一坐标</h3>\n<p>在 DC-Gen 的服务视角里，一条请求不是一个标量，而是一个三元组：分辨率、采样步数、以及期望的端到端时限。步数直接决定这条请求要过多少遍 DiT 主干，也就决定了它的“计算重量”。压缩潜空间改变的不是步数，而是每一步的张量规模——因此负载形态的第一坐标仍然是步数分布，压缩比只是把每步的单价压低。测量口径必须把这两者分开记录：单步延迟（step latency）与步数（N）相乘才是纯采样时间，再叠加压缩解码器的一次性开销，才构成端到端延迟的骨架。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx N \\cdot t_{\\text{step}}(B, d_z, \\text{prec}) + t_{\\text{dec}}(B, d_z) + t_{\\text{queue}}$$</div>\n<p>其中 <em>d<sub>z</sub></em> 是压缩潜空间的维度，<em>B</em> 是批大小，prec 是潜变量的存放精度（FP8／NVFP4）。这个式子暴露了一个常被忽略的事实：压缩比同时进入两项，但进入方式不同——<em>t<sub>step</sub></em> 随 <em>d<sub>z</sub></em> 缩小而下降，且因为每步都要重复 N 次，收益被放大 N 倍；<em>t<sub>dec</sub></em> 只发生一次，收益不被放大。所以在高步数负载上，压缩潜空间的杠杆远大于在低步数负载上。工程判断由此而来：压缩比应当按步数分桶分别标定，而不是全局取一个值。</p>\n<p>具体例子：同一批请求里既有 8 步的快速草稿档，也有数十步的高质量档。前者端到端时间里解码占比高，压缩带来的每步收益被摊薄；后者每步收益被步数放大，尾延迟改善明显。若监控只报一个平均单步延迟，这个结构性差异会被完全掩盖——必须按步数桶分别出 P50／P99。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-9\">九 · 并发与批大小：压缩比与批大小是同一根显存杠杆的两端</h3>\n<p>并发上升时，调度器的第一反应是加大批大小以摊薄 DiT 前向的权重读取开销；但批大小受显存峰值约束，而显存峰值由三部分构成：主干权重、每步的激活与注意力中间量、以及压缩潜变量本身。压缩潜空间缩小的是后两项中的张量规模，因此它等价于“在不加显存的前提下把批做大”。测量口径应记录 <em>B</em> 与显存峰值的关系曲线，而不是只报一个最大批大小。</p>\n<ul>\n<li>每步激活峰值：与 <em>B</em>·<em>d<sub>z</sub></em> 近似成正比，压缩比直接压低斜率。</li>\n<li>注意力矩阵规模：序列长度由压缩潜变量的空间维度决定，压缩后注意力中间量按平方级下降，这是批大小能往上抬的主要空间来源。</li>\n<li>解码阶段峰值：一次性发生，输入规模随压缩比下降，但它与采样阶段的峰值不在同一时刻，容量规划要取两者较大者而非相加。</li>\n</ul>\n<p>代价的另一面是带宽。批越大，每步从显存读写的潜变量总量越大；把压缩潜变量以 FP8 或 NVFP4 存放能把这条带宽压下来，但低精度与压缩误差是叠加的，质量边界论文未给出。因此部署侧的可行做法是把“批大小×精度”当作二维网格逐格标定，记录每格的每步延迟与显存峰值，而不是先定精度再调批。</p>\n<p>具体例子：当并发翻倍而显存峰值逼近上限时，有两条路——降批大小，或把压缩潜变量降到更低精度。前者损失吞吐摊薄效应，后者引入额外数值误差。DC-Gen 的压缩比提供了第三条路：加深压缩，让同样显存装下更大批。三条路的取舍必须用同一套测量口径比较，否则无法判断哪条在尾延迟上更优。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-10\">十 · SLO 与长尾：尾延迟由最重的那条请求定义</h3>\n<p>SLO 通常写成端到端尾延迟的分位数约束，例如 P99 不超过某阈值。扩散服务的长尾来源很具体：高分辨率请求的潜变量空间维度更大，步数多的请求重复次数更多，两者相乘就是最重的请求。压缩潜空间对长尾的作用是非线性的——它同时缩小空间维度与每步张量，对最重请求的绝对削减量最大，因此尾延迟的改善往往比均值改善更显著。测量口径必须把请求按“分辨率×步数”分桶后各自统计尾延迟，混合统计会稀释这个效应。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{tail}}:\\ \\Pr\\{T_{\\text{e2e}} &gt; \\tau\\} \\le \\varepsilon,\\quad \\text{约束变量} = (d_z,\\ \\text{prec},\\ B_{\\text{桶}},\\ \\text{压缩比})$$</div>\n<p>排队时间 <em>t<sub>queue</sub></em> 是长尾的另一个来源，而它受批调度窗口影响：为了凑批而等待会拉长尾延迟，为了压尾延迟而减小批又会牺牲吞吐。压缩潜空间在这里的作用是降低单请求的显存占用，使调度器能在同一显存预算下维持更大的在途批，从而缩短凑批等待。这是一个间接但真实的 SLO 杠杆，测量时应记录队列深度与凑批等待时间的分布，而不只是记录计算时间。</p>\n<p>具体例子：一个以 P99 为约束的服务，若只优化平均每步延迟，可能在长尾桶上仍然越界，因为最重请求的步数与维度都处于分布上端。正确做法是对每个桶单独求“满足该桶 SLO 所需的最大批大小与压缩比组合”，再取全局可行解。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-11\">十一 · 负载塑造方案：分桶与压缩比的自洽</h3>\n<p>负载不是被动接受方案，它反过来决定方案参数。DC-Gen 的服务链路按分辨率与采样步数分桶合并请求，这意味着桶的划分本身就是方案的一部分：桶太粗，同批内张量形状不一致，压缩潜变量的维度无法统一，批处理失效；桶太细，每桶请求稀疏，凑批等待拉长尾延迟。压缩比的选择必须与桶划分联合决定——同一桶内的请求共享同一个压缩后的潜空间维度，才能形成规则张量。</p>\n<ul>\n<li>分桶键：分辨率决定压缩后空间维度，步数决定重复次数，两者共同决定该桶的计算重量与显存占用。</li>\n<li>压缩比按桶标定：高步数桶可以承受更深压缩，因为每步收益被放大且质量损失可通过步数补偿；低步数桶应保守。</li>\n<li>精度按桶标定：显存紧张的桶优先降精度，但需与压缩误差叠加后重新测质量。</li>\n</ul>\n<p>方案反过来限制负载的地方在于质量门槛。压缩比提高会累积重建误差，极端压缩下细节丢失，主干未重训带来的分布偏移可能让采样不稳定。这些约束会以“某些请求类型不可服务”或“某些桶必须走浅压缩”的形式回写到调度策略里，等效于对负载施加了一个准入过滤。测量口径应记录被降级或拒绝的请求比例，作为方案对负载反作用的量化指标。</p>\n<p>具体例子：若高分辨率桶在深压缩下质量不可接受，调度器可以把该桶固定到较浅压缩并接受更小的批大小，于是该桶的吞吐上限被方案锁定，容量规划必须按这个锁定值算，而不能按全局平均算。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-12\">十二 · 可核查的测量口径清单</h3>\n<p>论文未给出加速比、压缩比数值与质量指标，因此部署前的标定必须自建口径。以下口径可直接落地为监控字段，每一项都对应一个可观测的物理量，避免用“大概更快”糊过去。</p>\n<table class=\"mini\">\n<thead><tr><th>口径</th><th>测量对象</th><th>用途</th></tr></thead>\n<tbody>\n<tr><td>单步延迟分布</td><td>按桶统计 P50／P99 的 <em>t<sub>step</sub></em></td><td>分离步数与每步单价，判断压缩收益是否被步数放大</td></tr>\n<tr><td>解码一次性开销</td><td><em>t<sub>dec</sub></em> 及其占端到端比例</td><td>识别低步数桶的解码瓶颈</td></tr>\n<tr><td>显存峰值</td><td>采样阶段与解码阶段分别取峰值</td><td>容量规划取两者较大者，避免相加误判</td></tr>\n<tr><td>凑批等待</td><td>队列深度与等待时间分布</td><td>量化分桶粒度对尾延迟的影响</td></tr>\n<tr><td>质量指标</td><td>逐压缩比档位的重建与采样质量</td><td>确定每个桶可用的最深压缩比</td></tr>\n<tr><td>降级比例</td><td>被降精度或降压缩比的请求占比</td><td>衡量方案对负载的反作用强度</td></tr>\n</tbody>\n</table>\n<p>这些口径的共同要求是“按桶”而非“全局”。混合统计会把高步数桶的压缩收益与低步数桶的解码开销搅在一起，得出无法指导调参的平均值。另一个要求是“同时刻”：显存峰值必须标注是采样阶段还是解码阶段，否则两个不同时刻的峰值会被错误相加。</p>\n<p>具体例子：若某桶的 P99 单步延迟在深压缩后下降，但端到端 P99 未改善，说明瓶颈已从采样转移到凑批等待或解码，此时继续加深压缩是无效投入，应转向调整分桶粒度或解码侧优化。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-13\">十三 · 失败模式与工程判断</h3>\n<p>把压缩比当成免费加速旋钮是最常见的误判。压缩越深，重建误差越大，质量与吞吐的权衡必须逐档标定；论文未给出失败阈值，意味着每一档都要自己测。第二个失败模式是只测单请求延迟而不测批调度下的显存峰值：压缩潜变量与 FP8／NVFP4 存放叠加后，峰值显存可能越界，而这个越界只在并发上升时才暴露。第三个是忽略主干未重训带来的分布偏移——压缩空间与原模型训练分布不一致时，采样可能不稳定，表现为同桶内质量方差变大，这种不稳定性在均值指标上看不出来，必须看分位数。</p>\n<p>工程判断可以收敛成一句可执行的话：压缩比不是全局常数，而是按“分辨率×步数”桶标定的容量参数；每个桶的可行压缩比由质量下限与显存峰值共同夹逼，调度器在该可行域内选批大小与精度。测量口径必须能同时回答三个问题——每步便宜了多少、尾延迟改善了多少、质量掉了多少——缺一个就无法判断压缩比该往哪边调。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-14\">十四 · 压缩比作为容量杠杆时的负载边界与测量口径</h3>\n<p>DC-Gen 的收益不是无条件随并发线性放大的。压缩潜空间把 DiT 每步的注意力序列长度与线性层张量规模同步缩小，但服务侧真正的约束在批调度窗口：请求按分辨率与采样步数分桶，同桶合并成批以摊薄主干前向开销。若负载的步数分布分散，桶内可合并的请求变少，批大小被长尾请求拖低，压缩带来的每步节省就被批内空转抵消。可核查的口径是分桶命中率与桶内批大小分布，而不是只看单请求每步延迟。</p>\n<p>压缩比 λ 与显存峰值之间存在可标定的耦合关系。设压缩后潜变量维度为 <span class=\"formula\">$$d_c$$</span>，原始维度为 <span class=\"formula\">$$d_o$$</span>，压缩比 <span class=\"formula\">$$r=d_o/d_c$$</span>；注意力矩阵规模随序列长度平方变化，而序列长度由潜变量空间分辨率决定，因此每步显存近似按 <span class=\"formula\">$$1/r$$</span> 的通道项与分辨率项叠加下降。把压缩潜变量以 FP8/NVFP4 存放进一步压低带宽，但低精度与压缩误差叠加后的质量边界论文未给出，必须逐档标定。测量口径应记录：每档压缩比下的显存峰值、每步延迟、端到端尾延迟，以及同批请求的压缩比一致性——混合压缩比的批会让解码器输入规模不一致，破坏批内并行。</p>\n<table class=\"mini\"><thead><tr><th>负载变量</th><th>对方案的作用</th><th>失效条件</th></tr></thead><tbody><tr><td>步数分布</td><td>决定分桶粒度与批大小</td><td>长尾步数请求拉低桶内批大小</td></tr><tr><td>分辨率</td><td>决定压缩后序列长度</td><td>高分辨率下压缩比不足，显存越界</td></tr><tr><td>并发</td><td>压缩比作为容量自由度</td><td>并发上升时降批或降精度仍越界</td></tr><tr><td>压缩比一致性</td><td>保证解码批并行</td><td>混合压缩比批导致解码输入不齐</td></tr></tbody></table>\n<p>反过来，方案也限制负载形态：压缩空间由后训练编解码器定义，主干未重训，压缩空间与原模型训练分布的偏移在极端压缩下可能让采样不稳定，失败阈值未量化。因此调度器不能把任意分辨率与步数自由混排，必须把压缩比作为分桶键的一部分，并在显存峰值逼近预算时优先降批大小或把潜变量转低精度，而不是继续加深压缩。SLO 规划应以每步延迟与端到端尾延迟双指标衡量，并把压缩比对应的质量指标纳入监控，否则容量规划会建立在未标定的质量边界上。</p>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-15\">十五 · 压缩潜变量如何改写算子形状</h3>\n<p>DC-Gen 的压缩编码器把原始潜变量从 <span class=\"inline-math\">dim(z_orig)</span> 压到 <span class=\"inline-math\">dim(z)</span>，这一步在算子层面不是“少存一点显存”，而是把 DiT 每步前向的矩阵乘形状整体改写。设压缩后潜变量序列长度为 <span class=\"inline-math\">S</span>、通道数为 <span class=\"inline-math\">C</span>，原始为 <span class=\"inline-math\">S_0</span>、<span class=\"inline-math\">C_0</span>，则单步注意力得分矩阵从 <span class=\"inline-math\">S_0×S_0</span> 缩到 <span class=\"inline-math\">S×S</span>，QKV 投影的权重矩阵乘从 <span class=\"inline-math\">(S_0·C_0)×d</span> 缩到 <span class=\"inline-math\">(S·C)×d</span>。对 Blackwell 上的 tcgen05 MMA 而言，这意味着每个 CTA 要搬运的 A/B 操作数 tile 数下降，TMEM 中驻留的累加器占用也随之下降——TMEM 是 SM 内一块容量固定、按列分配的累加器存储，tile 形状变小直接释放出可并行的 MMA 槽位。代价面在于：压缩编码器本身是一次额外的卷积/线性前向，解码器是一次额外的像素还原，二者把开销从“每步重复”挪到“每请求一次”，所以压缩比越高，摊薄效应越明显，但单次编解码的绝对延迟会成为短步数请求的新瓶颈。举例：一个 1024×1024 图像请求若原始潜空间序列长度为数千、压缩后降到数百，则每步注意力的得分矩阵元素数按平方级下降，而编解码器只在首尾各跑一次；当采样步数只有个位数时，这笔固定开销占比上升，调度器应把这类请求与高步数请求分桶，避免用同一压缩档位硬套。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-16\">十六 · 数据类型分层：FP16/BF16 到 FP8 再到 NVFP4</h3>\n<p>压缩潜空间的数值精度要分三层看，不能一刀切。第一层是 DiT 主干的权重与激活：主干被冻结或轻微微调，其数值行为由原模型决定，通常维持 BF16 以保住动态范围，因为扩散去噪的速度场预测对激活离群值敏感，BF16 的 8 位指数比 FP16 更耐受。第二层是压缩潜变量本身：它是每步反复读写的热数据，放在 FP8（E4M3）可把每步潜变量读写带宽减半，而 E4M3 的 4 位指数对压缩后已归一化的低维表示通常够用；若进一步降到 NVFP4，则采用块级缩放（每若干元素共享一个 FP8 缩放因子）来弥补 4 位尾数的精度损失，块缩放让量化误差在局部被吸收，而不是全局累积。第三层是编解码器：编码器输出即潜变量，其输出层需与潜变量的存储精度对齐，否则每次采样都要做一次精度转换，反而增加 kernel 启动与带宽开销。公式上，块量化的反量化可写为</p>\n<div class=\"formula\">$$\\hat{x}_i = s_b \\cdot q_i,\\quad s_b = \\frac{\\max_{j\\in b}|x_j|}{q_{\\max}},\\quad q_i\\in[-q_{\\max},q_{\\max}]$$</div>\n<p>其中 <span class=\"inline-math\">b</span> 是一个缩放块，<span class=\"inline-math\">q_max</span> 由 4 位或 8 位格式决定。逐项解释：<span class=\"inline-math\">s_b</span> 是块内最大绝对值归一化出的缩放，<span class=\"inline-math\">q_i</span> 是量化后的整数码字，反量化把码字乘回缩放。代价是每个块要多存一个缩放因子，块越小精度越好但元数据开销越大；在 NVFP4 下典型块大小取 16 或 32 个元素，元数据占比在潜变量这种低维张量上不可忽略，需与 tile 对齐以免破坏 tcgen05 的连续访存。工程判断：压缩比高、潜变量维度小时，NVFP4 的元数据开销占比上升，FP8 往往是更稳的默认档；压缩比低、张量大时 NVFP4 的带宽收益才压得过元数据成本。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-17\">十七 · 累加精度与误差传播</h3>\n<p>低精度输入不等于低精度累加。tcgen05 MMA 在 Tensor Core 内以更高位宽累加（FP32 累加器驻留 TMEM），所以 FP8 或 NVFP4 的乘加本身不会把误差直接堆进结果，真正的误差源有三处：输入量化的舍入、块缩放的截断、以及跨步传播。跨步传播是扩散采样特有的：第 <span class=\"inline-math\">t</span> 步的潜变量误差会作为第 <span class=\"inline-math\">t-1</span> 步的输入，误差沿采样链累积。设单步引入的相对误差为 <span class=\"inline-math\">ε_q</span>，采样步数为 <span class=\"inline-math\">T</span>，在最坏线性放大假设下终端误差量级为</p>\n<div class=\"formula\">$$\\varepsilon_{\\text{end}} \\lesssim \\sum_{t=1}^{T} \\left(\\prod_{k=t+1}^{T} \\|J_k\\|_2\\right)\\varepsilon_{q,t}$$</div>\n<p>其中 <span class=\"inline-math\">J_k</span> 是第 <span class=\"inline-math\">k</span> 步去噪映射的雅可比，其谱范数刻画该步对扰动的放大能力。逐项解释：外层求和遍历每一步注入的量化误差，内层乘积是后续各步对该误差的放大链；若某几步的 <span class=\"inline-math\">‖J‖</span> 接近或超过 1，误差不被衰减，低精度就必须收紧。这解释了为什么“压缩误差”与“低精度误差”不能分开标定：压缩改变的是潜空间分布与 <span class=\"inline-math\">J_k</span> 的谱性质，主干未重训意味着 <span class=\"inline-math\">J_k</span> 仍是原模型在原始潜空间上的雅可比，压缩后分布偏移可能让放大链变陡。代价面：为压住误差而提高累加或保留 BF16 潜变量，会直接抵消带宽收益；工程上应逐压缩档位测端到端质量指标，而不是假设 FP8 一定安全。例子：高压缩比档位下若发现细节纹理先退化，优先把潜变量从 NVFP4 升回 FP8，而不是动主干精度，因为主干精度改动影响所有请求而潜变量精度可按桶分级。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-18\">十八 · Blackwell 特性在压缩潜空间上的落点</h3>\n<p>tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core 对 DC-Gen 的价值不在峰值算力，而在小张量下的效率。压缩后的潜变量使单次 MMA 的 M/N/K 变小，若仍用单 SM 的 MMA，tile 填不满会导致 Tensor Core 利用率下滑；2-SM MMA 让一对 SM 协同执行一个更大的 MMA 指令，把两个 SM 的 TMEM 拼成更大的累加器空间，从而在压缩后仍能凑出足够大的 K 维与 N 维来喂满流水线。TMEM 的作用是让累加器不占寄存器文件，压缩潜变量带来的小 tile 意味着 TMEM 分配更灵活，可以同时驻留更多并发 MMA 的累加结果，提升批内多请求的并行度。第五代 Tensor Core 对 FP8/NVFP4 的原生支持让块缩放量化在硬件内完成反量化与乘加，避免单独的 dequant kernel——这是压缩潜变量能以低精度存放而不引入额外 kernel 启动的关键。代价面：2-SM MMA 要求两个 SM 的 tile 布局严格对齐，压缩后若序列长度不是 tile 的整数倍，尾块会浪费一半协同算力；因此压缩比的选择应与 tile 尺寸对齐，而不是取任意实数。工程判断：在批调度侧，把压缩后序列长度按 tile 边界分桶，比单纯按分辨率分桶更能保住 2-SM MMA 的利用率；显存峰值下降释放出的预算应优先给批大小而非给更高压缩比，因为批大小摊薄的是每步固定开销，压缩比摊薄的是每步张量规模，两者边际收益不同。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-19\">十九 · 精度与压缩叠加的容量核算</h3>\n<p>把压缩比与存放精度作为两个正交旋钮后，显存与带宽的核算可以写成乘积形式。设原始潜变量每请求显存为 <span class=\"inline-math\">M_0</span>，压缩比为 <span class=\"inline-math\">r</span>（维度缩减倍数），存放位宽从 <span class=\"inline-math\">b_0</span> 位降到 <span class=\"inline-math\">b</span> 位，则压缩潜变量显存约为</p>\n<div class=\"formula\">$$M \\approx \\frac{M_0}{r}\\cdot\\frac{b}{b_0} + M_{\\text{meta}}(r,b)$$</div>\n<p>逐项解释：第一项是主体张量按维度与位宽的双重缩减，第二项是块缩放元数据与对齐填充带来的附加占用，它在 <span class=\"inline-math\">r</span> 大、<span class=\"inline-math\">b</span> 小时占比上升。带宽侧同理，每步读写量按同一比例下降，但编解码器的一次性读写不随 <span class=\"inline-math\">r</span> 线性下降，因为解码器输出仍是全分辨率像素。这给出一个明确的工程边界：当采样步数 <span class=\"inline-math\">T</span> 较小，编解码固定开销在端到端延迟中占比升高，此时继续加深压缩的边际收益递减；当 <span class=\"inline-math\">T</span> 较大，每步带宽节省被重复 <span class=\"inline-math\">T</span> 次，压缩与低精度叠加的收益才充分释放。例子：调度器可按 <span class=\"inline-math\">T</span> 分两档——高步数桶用深压缩加 NVFP4 潜变量，低步数桶用浅压缩加 FP8 甚至 BF16，避免短请求被编解码固定开销拖累尾延迟。监控侧应记录每桶的每步延迟、显存峰值与质量指标，把压缩比与精度档位作为容量规划的自由度，而不是全局统一配置。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-20\">二十 · 失败模式与 kernel 级判断</h3>\n<p>最典型的失败是把压缩比与低精度当成两个独立免费旋钮同时拧到底：压缩误差改变潜空间分布，低精度误差在分布偏移后的雅可比链上被放大，二者叠加的质量退化不是各自退化的简单相加，且论文未给出叠加后的质量边界。第二个失败是忽略 tile 对齐：压缩后序列长度非 tile 整数倍时，2-SM MMA 的尾块浪费协同算力，实测吞吐可能低于预期，而单看显存占用会误判为“还有余量”。第三个失败是只测单请求延迟：压缩潜变量以 FP8/NVFP4 存放后，批内多请求的显存峰值与 TMEM 分配竞争在并发上升时才暴露，单请求测试看不到越界风险。kernel 级判断应落在三处：潜变量的存储布局是否与 tcgen05 的 tile 形状对齐、块缩放元数据是否与主数据连续排布以避免额外 gather、编解码器的输出层是否直接产出目标精度以避免每步转换。这三处任一不满足，压缩带来的带宽收益就会被额外的 kernel 启动与访存模式打散，端到端延迟不降反升。</p>\n\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-21\">二十一 · 压缩潜空间的数值边界：低精度算子与误差叠加</h3>\n<p>压缩潜空间真正落到 Blackwell 上时，瓶颈从“算不动”变成“存不准”。压缩后的潜变量维度变小，DiT 每步的注意力矩阵与线性层张量同步缩小，但这批张量要喂给 tcgen05 驱动的第五代 Tensor Core，就必须先决定数据格式：BF16 保底、FP8 提带宽、NVFP4 再压一半。问题在于压缩编码器本身已引入重建误差，低精度存放又叠加一层量化误差，两者不是简单相加而是沿采样步数累积。设压缩误差为 ε_c、量化误差为 ε_q，单步潜变量扰动近似为</p>\n<div class=\"formula\">$$\\delta_t \\approx \\varepsilon_c + \\varepsilon_q + J_\\theta\\,\\delta_{t-1},\\quad \\|\\delta_T\\| \\lesssim \\sum_{k=0}^{T-1}\\|J_\\theta\\|^{k}\\,(\\varepsilon_c+\\varepsilon_q)$$</div>\n<p>其中 J_θ 是 DiT 单步去噪映射的雅可比，T 为采样步数。这个式子说明两件事：步数越多，误差放大越明显；压缩比越深，ε_c 越大，低精度档位越激进，ε_q 越大。因此 FP8／NVFP4 存放压缩潜变量不是免费的带宽红利，它把质量边界从“压缩比单旋钮”变成“压缩比 × 精度档位”的二维曲面，而论文未给出该曲面的失败阈值。工程上必须逐档标定：固定压缩比扫精度，或固定精度扫压缩比，记录每步延迟、显存峰值与质量指标，找出 ε_c+ε_q 尚未触发可见细节丢失的拐点。</p>\n<p>累加精度是第二个容易踩空的地方。tcgen05 的 MMA 在 TMEM 中累加，FP8 输入的乘加链若用 FP32 累加尚可，但 NVFP4 的块缩放（block scaling）会引入每块共享指数，缩放因子选错时小块动态范围被截断，误差在注意力 softmax 前就被放大。2-SM MMA 把两个 SM 的 Tensor Core 协同做更大 tile，吞吐上去了，但跨 SM 的累加顺序与 TMEM 布局要求 kernel 侧显式对齐，否则数值不一致会以“偶发画质抖动”的形式出现，而不是稳定报错。这类失效在单请求延迟测试里几乎看不见，只有在批调度合并同桶请求、显存峰值逼近上限时才暴露。</p>\n<table class=\"mini\"><thead><tr><th>档位</th><th>带宽占用</th><th>误差来源</th><th>系统代价</th></tr></thead><tbody><tr><td>BF16 潜变量</td><td>基准</td><td>仅 ε_c</td><td>显存峰值最高，批大小受限</td></tr><tr><td>FP8 潜变量</td><td>约减半</td><td>ε_c+ε_q</td><td>需标定缩放因子，尾延迟改善依赖批合并</td></tr><tr><td>NVFP4 潜变量</td><td>再减半</td><td>ε_c+ε_q+块缩放截断</td><td>TMEM 布局与 2-SM tile 对齐成本上升</td></tr></tbody></table>\n<p>系统代价的落点在显存带宽与解码峰值。压缩潜变量以 FP8／NVFP4 存放确实压低每步读写带宽，但压缩解码器一次性还原像素时输入规模虽随压缩比下降，解码器权重与中间激活仍占显存；若把解码也塞进低精度，像素重建项 λ 对应的保真度会进一步劣化。更现实的判断是：压缩比与精度档位应联合作为容量规划自由度，而不是把 NVFP4 当成默认档。并发上升时先降批大小、再降精度，监控侧同时记录每步延迟、显存峰值与压缩比对应的质量指标；一旦发现主干未重训导致的分布偏移在极端压缩下让采样不稳定，就应回退压缩比而非继续压精度——因为 ε_c 是结构性的，ε_q 只是叠加项，先修大的那个。</p>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-22\">二十二 · 显存账本的三层结构：权重、激活、KV</h3>\n<p>在压缩潜空间里跑扩散采样，显存不是一块模糊的总量，而是一张必须逐项列出的账本。三层结构决定了优化顺序：第一层是常驻权重，DiT 主干在冻结状态下其参数张量在整个服务周期内不动，压缩编码器与解码器只在请求入口和出口各跑一次，权重占比小但不可分页；第二层是每步激活，压缩潜变量 <em>z</em> 及其在注意力与 MLP 中的中间张量，随批大小与序列长度线性放大，是峰值显存的主要来源；第三层是 KV 式中间缓存，扩散采样不像自回归那样有跨请求复用的 KV，但每步注意力需要保留当前步的 K/V 投影，若做步间缓存复用（例如固定 schedule 下的跨步特征复用）则这部分会累积。</p>\n<p>账本的基本恒等式是：</p>\n<div class=\"formula\">$$M_{\\text{peak}} = \\underbrace{W\\cdot b_w}_{\\text{权重}} + \\underbrace{B\\cdot S\\cdot d\\cdot b_a\\cdot k}_{\\text{激活}} + \\underbrace{B\\cdot S\\cdot d\\cdot b_{kv}\\cdot L_{\\text{cache}}}_{\\text{KV 缓存}} + M_{\\text{workspace}}$$</div>\n<p>其中 <em>B</em> 为批大小，<em>S</em> 为压缩潜空间的序列长度，<em>d</em> 为通道维，<em>b</em> 为每元素字节数，<em>k</em> 为激活张量倍数（注意力矩阵、FFN 中间层等叠加），<em>L</em><sub>cache</sub> 为缓存的步数。压缩比直接作用在 <em>S</em> 与 <em>d</em> 上：若压缩把 <em>S</em> 从原始潜空间的高维网格降到更短的序列，注意力矩阵从 <em>S</em>² 量级回落，激活项按平方关系缩小，这是 DC-Gen 相对“只降精度”方案的结构性优势。代价是编码器与解码器各引入一次额外前向，解码器输入规模虽随压缩比下降，但其权重仍需常驻，且解码在请求尾部一次性执行，会抬高端到端尾延迟中解码段的占比。</p>\n<p>具体例子：一个按分辨率与步数分桶的服务，同桶请求合并后 <em>B</em> 上升，激活项线性放大而权重项不变，因此批调度的显存杠杆集中在激活与 KV 缓存上；此时把压缩潜变量从 FP16 降到 FP8，<em>b</em><sub>a</sub> 减半，等效于在不改压缩比的前提下把可容纳批大小翻倍，但低精度与压缩误差叠加后的质量边界论文未给出，必须逐档标定。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-23\">二十三 · 分页与复用：把压缩潜变量当成可换出的页</h3>\n<p>扩散采样的显存行为与自回归解码不同：没有跨请求增长的 KV 历史，但有跨步反复读写的潜变量缓冲区。分页的价值不在于容纳无限上下文，而在于把“当前步活跃张量”与“已完成步的中间结果”分离。工程上可把每步的潜变量与注意力中间结果按固定大小的页管理，页的粒度对齐压缩潜空间的通道块，使一次 DiT 前向只触碰当前步所需的页集合；已完成步的页若被后续步引用（例如多步 schedule 中的残差复用），则留在显存池，否则换出到主机侧。</p>\n<p>复用有两个层次。第一层是批内复用：同桶请求共享同一组压缩编码器输出形状与采样 schedule，调度器可让它们的潜变量缓冲区按页对齐分配，减少碎片。第二层是步间复用：若采样器在某几步复用上一步的注意力 K/V 投影（固定 schedule 下的近似），则 KV 缓存项 <em>L</em><sub>cache</sub> 大于 1，账本中该项不可忽略；反之若每步重算，则 <em>L</em><sub>cache</sub>=1，显存换带宽。这是一个明确的工程取舍：缓存换显存，重算换带宽。</p>\n<p>伪代码思路：</p>\n<div class=\"formula\">$$\\text{for } t \\text{ in schedule: } \\quad z_t \\leftarrow \\text{DiT}(z_{t-1}, t);\\quad \\text{if } \\text{keep}(t): \\text{pool.pin}(z_t) \\text{ else } \\text{pool.evict}(z_t)$$</div>\n<p>代价落在带宽上：换出与换入走 PCIe 或主机内存，单次页搬移的延迟会叠加到每步延迟上；若换出发生在采样中段，尾延迟抖动明显。因此分页策略应把换出点放在步与步之间的批边界，而不是任意步内。压缩潜空间让页更小，单页搬移成本下降，这是压缩比在分页场景下的隐性收益。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-24\">二十四 · 带宽瓶颈：HBM3e 容量与每步读写量</h3>\n<p>Blackwell 档位的 HBM3e 容量决定了账本的上限，但吞吐瓶颈往往不在容量而在每步读写量。扩散采样每步要读一遍压缩潜变量、写一遍新潜变量，注意力还要读写 K/V 投影与注意力矩阵。每步的显存流量近似为：</p>\n<div class=\"formula\">$$\\text{Traffic}_{\\text{step}} \\approx B\\cdot S\\cdot d\\cdot b_a\\cdot(\\alpha_{\\text{read}}+\\alpha_{\\text{write}}) + B\\cdot S^2\\cdot b_{\\text{attn}}$$</div>\n<p>其中 <em>α</em> 为读写倍数，<em>b</em><sub>attn</sub> 为注意力矩阵元素字节。压缩比降低 <em>S</em> 时，第二项按平方下降，第一项线性下降，因此深压缩对带宽的收益在注意力项上最显著。把压缩潜变量以 FP8 或 NVFP4 存放，则 <em>b</em><sub>a</sub> 与 <em>b</em><sub>attn</sub> 同步下降，但 NVFP4 的块缩放元数据会引入额外字节，实际收益需按块大小折算，不能简单按位宽比例估算。</p>\n<p>容量侧的可复算预算：设单卡 HBM3e 容量为 <em>C</em>，权重占 <em>W</em><sub>0</sub>，工作区与框架开销占固定比例 <em>r</em>，则可用于激活与 KV 的余量为 <em>C</em>(1−<em>r</em>)−<em>W</em><sub>0</sub>。给定压缩比对应的 <em>S</em>、<em>d</em> 与精度字节 <em>b</em><sub>a</sub>，最大批大小为：</p>\n<div class=\"formula\">$$B_{\\max} = \\left\\lfloor \\frac{C(1-r)-W_0}{S\\cdot d\\cdot b_a\\cdot k + S\\cdot d\\cdot b_{kv}\\cdot L_{\\text{cache}}} \\right\\rfloor$$</div>\n<p>这个式子可直接用于容量规划：压缩比提高使分母缩小，<em>B</em><sub>max</sub> 上升；精度从 FP16 降到 FP8 使 <em>b</em> 减半，效果类似。具体例子：若某档压缩比把 <em>S</em> 减半、<em>d</em> 减半，分母降至约四分之一，同等余量下批大小约翻四倍，但解码器与编码器的额外权重和一次性解码峰值会吃掉一部分余量，实际增益需按账本逐项扣减。论文未给出具体容量与压缩比数值，部署前必须用本式代入实测的 <em>S</em>、<em>d</em> 与精度档位标定。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-25\">二十五 · 卸载与低精度叠加：压缩比之外的第二个旋钮</h3>\n<p>当账本仍越界时，卸载是最后手段：把冻结的 DiT 主干权重或压缩解码器权重放到主机侧，按需换入。扩散采样的权重访问模式是每步全量读取主干，卸载会引入每步的权重搬移流量，直接冲击每步延迟；因此卸载只适合把编码器/解码器这类低频调用的权重移出，主干权重应常驻。压缩潜空间的另一个旋钮是低精度存放：压缩潜变量以 FP8 或 NVFP4 存放，降低每步带宽占用，但压缩误差与量化误差叠加，质量边界未量化，必须按压缩比档位分别标定。</p>\n<p>工程判断的顺序应是：先调压缩比（结构性降低 <em>S</em> 与 <em>d</em>），再调精度（降低 <em>b</em>），最后才动批大小与卸载。原因是压缩比同时降低算力与带宽，精度只降带宽不降算力，卸载则增加延迟。监控侧需记录每步延迟、显存峰值与压缩比对应的质量指标，把压缩比作为容量规划的自由度：并发上升时优先降批大小或把压缩潜变量转 FP8/NVFP4，避免显存峰值越界。</p>\n<p>失败模式在此处最集中：把压缩比当成免费加速旋钮，压缩越深重建误差越大；只测单请求延迟不测批调度下的显存峰值，压缩潜变量与低精度存放叠加后峰值可能越界；忽略主干未重训带来的分布偏移，压缩空间与原模型训练分布不一致时采样可能不稳定。这些都不是账本公式能自动兜住的，必须在容量规划里留出质量与稳定性的余量。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-26\">二十六 · 压缩潜空间的显存账本：从张量形状到峰值预算</h3>\n<p>DC-Gen 的显存收益不是一句“潜空间变小了”就能兑现的，它必须落到张量形状上才可复算。设原始潜变量为 <span class=\"inline-math\">z_orig ∈ R^{C×H×W}</span>，压缩后为 <span class=\"inline-math\">z ∈ R^{c×h×w}</span>，压缩比 <span class=\"inline-math\">r = (C·H·W)/(c·h·w)</span>。DiT 把潜变量切成 patch 序列，序列长度 <span class=\"inline-math\">N = (h·p^{-1})·(w·p^{-1})</span>，注意力矩阵为 <span class=\"inline-math\">N×N</span>，线性层权重按通道 <span class=\"inline-math\">c</span> 缩放。于是每步显存占用近似为</p>\n<div class=\"formula\">$$M_{\\text{step}} \\approx \\underbrace{N^2 b_a}_{\\text{注意力图}}+\\underbrace{N\\,c\\,b_x}_{\\text{激活}}+\\underbrace{W_{\\text{DiT}}\\,b_w}_{\\text{冻结权重}}+\\underbrace{N\\,c\\,b_{kv}}_{\\text{中间缓存}}$$</div>\n<p>其中 <span class=\"inline-math\">b_a, b_x, b_{kv}, b_w</span> 分别是注意力图、激活、缓存与权重的每元素字节数。关键判断是：<b>权重项不随压缩比变化</b>，因为主干冻结；真正被压缩比撬动的是前三项。当 <span class=\"inline-math\">r</span> 提高时 <span class=\"inline-math\">N</span> 与 <span class=\"inline-math\">c</span> 同时下降，注意力图按 <span class=\"inline-math\">N^2</span> 二次收缩，这是 DC-Gen 显存账本里最陡的一条曲线。举例：若 <span class=\"inline-math\">h,w</span> 各减半、<span class=\"inline-math\">c</span> 减半，则 <span class=\"inline-math\">r=8</span>，<span class=\"inline-math\">N</span> 降到 1/4，注意力图降到 1/16，而权重项纹丝不动——这意味着在 B200 这类权重占比高的档位上，压缩比带来的峰值下降会被权重项“托底”，收益存在天花板。</p>\n<p>把压缩潜变量以 FP8 或 NVFP4 存放，是把 <span class=\"inline-math\">b_x</span> 与 <span class=\"inline-math\">b_{kv}</span> 再压一档的手段，但它与压缩误差是<b>叠加</b>而非抵消：重建项系数 <span class=\"inline-math\">λ</span> 管的是编解码器的空间压缩失真，低精度管的是数值量化失真，两者都作用在同一个潜变量上。工程上必须把这两条误差源分开标定：先用 FP16/BF16 潜变量扫 <span class=\"inline-math\">r</span> 找到质量可接受档位，再在该档位上单独开 FP8/NVFP4，观察质量指标是否越界；若一次性同时调 <span class=\"inline-math\">r</span> 与精度，失败时无法归因。失效条件是明确的：当 <span class=\"inline-math\">λ</span> 偏小、<span class=\"inline-math\">r</span> 偏大时，解码器还原的像素细节先崩，此时再降精度只会加速崩坏，而显存账本上看到的“省了”是假省。</p>\n<p>KV 式中间缓存这一项容易被误读。扩散采样不像自回归那样有随序列增长的 KV cache，但每步 DiT 前向仍要保留注意力中间量与跨步复用的潜变量缓冲；压缩后 <span class=\"inline-math\">N·c</span> 变小，这部分缓存随之缩小，<b>但它不随步数线性累积</b>，所以“步数多所以缓存大”的直觉是错的。真正的带宽瓶颈在每步对压缩潜变量的反复读写：<span class=\"inline-math\">N·c·b_x</span> 字节在数十步里被反复搬运，HBM3e 带宽吃紧时，压缩比提高带来的字节数下降直接转化为每步延迟下降，这比算力节省更早触到瓶颈。可复算的预算写法是：给定分辨率、<span class=\"inline-math\">r</span>、精度与批大小 <span class=\"inline-math\">B</span>，峰值 <span class=\"inline-math\">\\(M_{\\text{peak}} \\approx B·M_{\\text{step}} + M_{\\text{VAE}}\\)</span>，其中 <span class=\"inline-math\">\\(M_{\\text{VAE}}\\)</span> 是解码器一次性还原的输入规模，随 <span class=\"inline-math\">r</span> 下降但不随 <span class=\"inline-math\">B</span> 摊薄——解码是逐请求的，批调度摊不薄它。因此容量规划要把“DiT 批内摊薄”和“VAE 逐请求固定”分开算，压缩比在两者上的杠杆率不同。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随压缩比 r 的变化</th><th>随精度变化</th><th>随批大小 B 的变化</th></tr></thead><tbody><tr><td>DiT 冻结权重</td><td>不变</td><td>可降（若量化权重）</td><td>不变</td></tr><tr><td>注意力图 N²</td><td>二次下降</td><td>线性下降</td><td>线性增长</td></tr><tr><td>潜变量读写带宽</td><td>线性下降</td><td>线性下降</td><td>线性增长</td></tr><tr><td>VAE 解码输入</td><td>线性下降</td><td>线性下降</td><td>不摊薄</td></tr></tbody></table>\n<p>边界条件落在两处。其一，<b>权重托底</b>：当压缩比已把激活与注意力压到远小于冻结权重时，继续提 <span class=\"inline-math\">r</span> 的显存边际收益趋零，而重建误差仍在累积，此时正确动作是停止提压缩比、转而降精度或调批大小。其二，<b>分布偏移</b>：主干未重训，压缩空间与原模型训练分布不一致，极端压缩下采样可能不稳定，这种不稳定在显存账本上不可见，只能靠监控侧把压缩比与质量指标绑定记录来暴露。服务侧的工程判断是：把 <span class=\"inline-math\">r</span> 当作容量规划的自由度而非免费加速旋钮，显存峰值越界时优先降批大小或降精度，而不是继续压潜空间——因为后者的质量代价不可逆，前两者可回退。</p>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-27\">二十七 · 分桶与批组装：压缩潜空间改变了批的粒度</h3>\n<p>DC-Gen 把采样搬到低维潜空间之后，调度器面对的不再是“一个请求一张高维潜变量”，而是“一个请求一张压缩潜变量”。这个变化直接改写了批的组装逻辑：批的显存占用由 <span class=\"inline-math\">B × dim(z) × dtype_bytes</span> 决定，而 <span class=\"inline-math\">dim(z)</span> 被压缩比整体缩放，于是同一个显存预算下能塞进更多请求，或者同一批大小下每步的注意力矩阵更小。调度器仍按分辨率与采样步数分桶，但分桶的边界要重新标定：压缩比对不同分辨率的收益并不均匀，高分辨率输入经编码器压到同一低维空间后，桶内张量形状趋于一致，跨分辨率的批合并反而变得可行。工程上的代价是编码器前向本身要占一份显存与一份延迟，它发生在批组装之前、逐请求执行，无法被批摊薄，因此编码器延迟必须计入端到端 SLO 的固定开销项，而不是当作可忽略的预处理。</p>\n<p>批组装的具体机制可以写成：对每个桶维护一个待组批队列，队列头部按到达时间排序，组批时取队首若干请求，检查 <span class=\"inline-math\">B × dim(z) × bytes + B × dim(z) × steps × cache_bytes</span> 是否落在显存水位线以下，越界则截断批。这里 <span class=\"inline-math\">cache_bytes</span> 是每步中间缓存的单请求占用，压缩后它随 <span class=\"inline-math\">dim(z)</span> 线性下降，所以显存水位线对批大小的约束被显著放松。举例：若压缩把潜变量通道数压到原来的四分之一，注意力序列长度随之缩短，单请求每步缓存占用降到原来的量级以下，同一张 B200 的显存预算可以支撑更大的并发批，但这一步的收益必须用实测的每步延迟曲线来确认，因为批变大后单步计算时间上升，吞吐与尾延迟的平衡点会移动。</p>\n<div class=\"formula\">$$T_{\\text{batch}}(B)=T_{\\text{enc}}+N_{\\text{steps}}\\cdot T_{\\text{step}}(B)+T_{\\text{dec}},\\quad T_{\\text{step}}(B)\\approx a+bB^{\\gamma}$$</div>\n<p>上式里 <span class=\"inline-math\">\\(T_{\\text{enc}}\\)</span> 与 <span class=\"inline-math\">\\(T_{\\text{dec}}\\)</span> 是逐请求的固定项，<span class=\"inline-math\">\\(T_{\\text{step}}(B)\\)</span> 随批大小次线性增长（<span class=\"inline-math\">γ&lt;1</span>），因此增大 B 摊薄的是步内开销而非编解码开销。压缩比越高，<span class=\"inline-math\">a</span> 与 <span class=\"inline-math\">b</span> 同时下降，但 <span class=\"inline-math\">\\(T_{\\text{enc}}\\)</span> 的相对占比上升——这是 DC-Gen 调度侧最容易被忽略的代价结构。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-28\">二十八 · 连续批处理与 chunked prefill 在扩散采样里的对应物</h3>\n<p>自回归推理里的连续批处理解决的是“请求长度不一、批内空转”的问题；扩散采样没有 token 级的变长输出，但有步数级的变长执行。DC-Gen 的采样器对每个请求跑固定或按调度策略决定的步数，步与步之间是严格的串行依赖，因此不能像 LLM 那样把不同请求的“第 k 步”和“第 k+1 步”交错进同一个批。可行的对应物是“步级流水”：把批内请求按当前步号分组，同一步号的请求合并执行 DiT 前向，不同步号的请求留在各自队列里等待下一轮组批。当批内请求步数分布分散时，这种分组会让有效批大小随步号衰减，尾部只剩少数请求在跑，单步延迟被摊薄的程度下降。压缩潜空间在这里的作用是降低衰减尾部的绝对代价：即使只剩一个请求在跑某一步，它的张量规模也已被压缩，空转批的浪费被压缩比打折。</p>\n<p>chunked prefill 的对应物是“分段解码”。DC-Gen 的压缩解码器一次性把最终潜变量还原为像素，但若解码输入规模仍构成尾延迟瓶颈，可以把解码按空间分块执行，每块独立还原并与响应流式写回。分块的代价是块边界处的感受野不完整，需要重叠采样或边界填充，重建质量在块缝处可能下降；收益是把一次性解码峰值显存切成多份，使解码阶段能与下一批的采样阶段在时间上重叠，提升流水线利用率。工程判断是：当解码占端到端延迟的比例超过采样单步延迟时，分段解码才值得引入，否则分块带来的质量风险不划算。</p>\n<ul>\n<li>机制：步级分组组批 + 解码空间分块，前者对抗步数分散，后者对抗解码峰值。</li>\n<li>代价：步级分组在步数分布方差大时有效批大小衰减，吞吐下降；分块解码引入块缝质量风险与额外填充计算。</li>\n<li>例子：一批 16 个请求，步数分别为 20 与 50 各半，前 20 步满批、后 30 步只有 8 个请求在跑，压缩后这 8 个请求的单步张量更小，衰减段的显存与带宽占用同步下降。</li>\n</ul>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-29\">二十九 · 优先级、抢占与压缩比作为调度维度</h3>\n<p>DC-Gen 给调度器多了一个传统 LLM 服务没有的旋钮：压缩比。压缩比在部署时通常固定，但若编解码器支持多档位（不同 <span class=\"inline-math\">dim(z)</span> 的编码器权重），调度器就可以按请求优先级动态选择档位——高优先级请求走低压缩比保质量，低优先级或批填充请求走高压缩比换吞吐。这本质上是把“抢占”从“换出显存”变成“换压缩档位”：被抢占的请求不必丢弃已算出的步，而是把当前潜变量按更高压缩比重新编码，继续在更小空间里跑剩余步数，显存占用立刻下降，代价是重建误差累积与一次额外的编码前向。</p>\n<p>抢占的判定条件是显存水位线与尾延迟 SLO 的联合约束：当新请求到达导致批组装越界，或队列中高优先级请求的预计完成时间超过 SLO，调度器触发档位切换。切换的代价要计入公式：<span class=\"inline-math\">\\(T_{\\text{switch}}=T_{\\text{re-enc}}+N_{\\text{remain}}\\cdot\\Delta T_{\\text{step}}\\)</span>，其中 <span class=\"inline-math\">\\(ΔT_{\\text{step}}\\)</span> 是档位切换后单步延迟的变化量（通常为负，即变快），<span class=\"inline-math\">\\(T_{\\text{re-enc}}\\)</span> 是重新编码的一次性开销。只有当剩余步数足够多、<span class=\"inline-math\">\\(N_{\\text{remain}}\\cdot|\\Delta T_{\\text{step}}|&gt;T_{\\text{re-enc}}\\)</span> 时切换才净收益为正，这个不等式就是抢占策略的触发阈值。极端压缩下重建误差累积的风险在此被放大：抢占越频繁，同一请求经历的档位切换越多，误差叠加越难控制，因此档位切换次数应设上限，或只允许单向切换（从低压缩到高压缩，不回切）。</p>\n<table class=\"mini\"><thead><tr><th>调度动作</th><th>触发条件</th><th>主要代价</th><th>收益来源</th></tr></thead><tbody><tr><td>降批大小</td><td>显存水位越界</td><td>吞吐下降</td><td>避免 OOM，保尾延迟</td></tr><tr><td>潜变量转 FP8/NVFP4</td><td>带宽瓶颈或显存紧张</td><td>低精度与压缩误差叠加</td><td>每步带宽占用下降</td></tr><tr><td>提高压缩档位（抢占）</td><td>高优先级请求等待超 SLO</td><td>重编码前向 + 误差累积</td><td>显存占用立刻下降</td></tr><tr><td>分段解码</td><td>解码占端到端延迟比例高</td><td>块缝质量风险</td><td>解码峰值显存切分、流水重叠</td></tr></tbody></table>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-30\">三十 · 分离式预填/解码在扩散链路里的映射</h3>\n<p>LLM 的分离式预填/解码把计算密集的 prefill 与访存密集的 decode 放到不同资源池。DC-Gen 链路的天然分界不在 prefill/decode，而在“编码 + 采样”与“解码”之间：编码器与 DiT 采样是计算密集段，压缩解码器是访存与显存峰值密集段，两者的资源画像不同。分离式部署可以把采样池与解码池分开，采样池按压缩潜空间的高并发配置，解码池按像素还原的显存峰值配置，中间通过压缩潜变量张量传递。传递的数据量是 <span class=\"inline-math\">B × dim(z) × bytes</span>，压缩比越高，跨池传输越轻，这正是 DC-Gen 对分离式架构的额外增益——潜空间压缩同时压小了池间通信量。</p>\n<p>分离的代价是池间同步与排队：解码池的排队长度会直接叠加到端到端尾延迟上，且解码池的批处理窗口与采样池的批组装节奏不一致时，会出现解码池空转或积压。工程上要给解码池设独立的批窗口与水位线，并让采样池在接近完成时提前通知解码池预留容量。举例：采样池一批 32 个请求在相近时刻完成采样，若解码池按 8 个一批处理，则最后 8 个请求要等前三批解码完成，尾延迟被解码池的批窗口拉长；把解码池批窗口调大或让解码分块流式写回，可以把这段排队压下去。压缩比在此的作用是让解码池单批的显存峰值下降，从而允许更大的解码批窗口，缓解排队。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-31\">三十一 · 尾延迟的压法：从 P99 反推批与步的预算</h3>\n<p>尾延迟的来源在 DC-Gen 链路上有三段：编码器逐请求串行、采样步数分散导致的批衰减尾部、解码池排队。压尾延迟的顺序应该是先压解码排队（它对 P99 的贡献最直接且与批窗口强相关），再压步数分散（通过分桶时把步数相近的请求归到一起，减少衰减段），最后才考虑编码器的批化——编码器逐请求执行，但若把同桶请求的编码也合并成一个批，编码前向的固定开销可被摊薄，代价是编码器批内张量规模上升，需要单独的显存预算。</p>\n<p>从 P99 反推预算的做法：给定 SLO 的端到端尾延迟上限 <span class=\"inline-math\">\\(T_{\\text{SLO}}\\)</span>，先扣除解码池的排队上界与编码器延迟，剩余预算分配给采样段：<span class=\"inline-math\">\\(N_{\\text{steps}}\\cdot T_{\\text{step}}(B_{\\text{tail}})\\le T_{\\text{SLO}}-T_{\\text{enc}}-T_{\\text{dec-queue}}\\)</span>，其中 <span class=\"inline-math\">\\(B_{\\text{tail}}\\)</span> 是衰减尾部的最小有效批大小。压缩比通过降低 <span class=\"inline-math\">\\(T_{\\text{step}}\\)</span> 直接放松这个不等式，但压缩比提高会带来质量指标下滑，容量规划时必须把质量下限作为约束一起解，而不是只解延迟不等式。监控侧记录每步延迟、显存峰值与压缩比对应的质量指标，正是为了在运行时判断当前档位是否已经逼近质量下限，从而触发档位回退或批大小调整。</p>\n<p>最后落在具体机制上：DC-Gen 的调度收益不来自某一个孤立技巧，而来自压缩潜空间把“批大小—步数—显存峰值”三者的耦合关系整体平移。部署时的工程判断是先把压缩比标定到质量可接受的最低档，再在该档位下重新测每步延迟曲线与显存水位线，用实测的 <span class=\"inline-math\">\\(T_{\\text{step}}(B)\\)</span> 反解批大小与解码池窗口，而不是沿用未压缩模型的调度参数——后者在压缩后必然过保守，浪费了压缩换来的容量杠杆。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-32\">三十二 · 压缩潜空间下的批调度边界：桶化、抢占与解码尾延迟</h3>\n<p>DC-Gen 把采样搬进低维潜空间后，调度器的分桶键要重新定义。原始方案按“分辨率×步数”分桶，但压缩后 DiT 每步的注意力序列长度由压缩潜变量的空间维度决定，而非像素分辨率——两个像素分辨率不同、压缩后潜变量网格相同的请求，其每步计算量几乎一致，应并入同桶以抬高批内利用率；反之，同一分辨率经不同压缩比档位编码后潜变量维度不同，必须分属不同桶，否则批内张量形状不齐，tcgen05 MMA 的 tile 划分退化，每步延迟被最慢样本拖住。桶键应取 <span>（压缩潜变量维度, 采样步数, 精度档）</span> 三元组，分辨率只作为质量标签而非调度键。批窗口的代价在于：压缩比越高，单请求每步张量越小，批可以开得更大，但压缩解码器一次性还原像素的峰值显存随批大小线性增长，且这一步不可与采样步流水重叠——解码是端到端尾延迟的独立台阶，批越大台阶越高。</p>\n<p>连续批处理在扩散采样上的失效条件很明确：扩散请求的步数是刚性循环，中途无法像自回归解码那样逐 token 插入新请求，只能在“整批跑完 N 步”与“按步抢占”之间取舍。按步抢占（step-level preemption）把批内请求的步计数对齐到最小公倍步数，短步数请求提前释放显存，代价是每步都要重排批内张量布局，重排开销与压缩潜变量的搬运量成正比——压缩比越高，单次重排越便宜，抢占粒度可以更细。chunked prefill 在此处的对应物是“分块编码”：压缩编码器对输入图像的编码可切块执行，把编码阶段与上一批的解码阶段拼在同一时间窗，填平解码台阶造成的 SM 空闲。优先级策略上，尾延迟敏感的请求应获得独占小批而非并入大批，因为大批的每步延迟由批内最慢样本决定，SLO 约束应写成 <span>P99 端到端 ≤ 步数×每步延迟上界 + 解码延迟上界</span>，其中每步延迟上界随批大小与压缩比档位标定，而非用平均吞吐反推。</p>\n<div class=\"formula\">$$\\text{SLO}_{p99}\\approx N_{\\text{step}}\\cdot \\big(t_{\\text{DiT}}(B,d_{\\text{lat}},\\text{prec})+\\epsilon_{\\text{reorder}}\\big)+t_{\\text{dec}}(B,d_{\\text{lat}})$$</div>\n<p>分离式预填/解码在 DC-Gen 下的映射不是常规的 prefill/decode 切分，而是“编码+采样”与“像素解码”两段分离：采样段吃算力与低带宽的压缩潜变量读写，解码段吃显存带宽与一次性峰值显存，两段对资源的需求方向相反，混布在同一组 SM 上会互相压制。把解码段放到独立实例、经 NVLink 5 传压缩潜变量而非像素，传输量随压缩比下降，这是分离式部署在此方案里唯一站得住的收益点；若压缩比不够深，传潜变量的带宽节省抵不过跨实例的调度与排队开销，分离反而抬高尾延迟。工程判断落在标定顺序上：先固定压缩比档位测出 <span>\\(t_{\\text{DiT}}(B,d_{\\text{lat}})\\)</span> 与解码峰值显存两条曲线，再决定批大小上限与是否分离；压缩比与 FP8/NVFP4 存放叠加时，低精度误差与重建误差同向累积，质量边界必须逐档实测，不能把压缩比当作免费加速旋钮直接拉满。</p>\n<table class=\"mini\"><thead><tr><th>调度决策</th><th>收益</th><th>失效条件</th></tr></thead><tbody><tr><td>按潜变量维度分桶</td><td>批内张量对齐，MMA tile 不退化</td><td>压缩比档位过多导致桶碎片化</td></tr><tr><td>按步抢占</td><td>短步数请求提前释放显存</td><td>重排开销超过释放收益</td></tr><tr><td>解码段分离部署</td><td>传潜变量省带宽，峰值显存隔离</td><td>压缩比不足时跨实例开销反超</td></tr></tbody></table>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-33\">三十三 · 压缩潜空间如何改写并行切分的成本函数</h3>\n<p>DC-Gen 把采样搬到低维潜空间后，并行策略的代价结构发生位移，而不是简单等比缩小。以 DiT 主干的张量并行（TP）为例，每层线性层的权重切分维度不变，但激活张量沿序列维缩小，TP 组内 All-Reduce 的通信量正比于批大小 × 序列长度 × 隐藏维 × 精度字节数。压缩比 r = dim(z_orig)/dim(z) 使序列长度按 r 缩短，于是单次 All-Reduce 的字节数近似按 1/r 下降，而权重分片本身的常驻显存不随 r 变化——这意味着 TP 度数的选择从“显存驱动”转向“通信驱动”：原来为了摊薄权重显存而被迫用高 TP 度，现在权重显存压力未减，但激活通信变便宜，TP 组内带宽不再是首要约束，反而可以把度数调低以换取更少的跨卡同步点。代价在于：TP 度数降低后单卡权重分片变大，若压缩潜变量又以 FP8 存放，权重仍占大头，显存峰值可能反而成为新瓶颈。工程判断是：压缩比提升后应重新扫描 (TP, 批大小) 组合，而不是沿用未压缩时的拓扑。</p>\n<div class=\"formula\">$$B_{\\text{AR}} \\approx 2 \\cdot b \\cdot s/r \\cdot h \\cdot \\text{sizeof(dtype)} \\cdot (N_{\\text{TP}}-1)/N_{\\text{TP}}$$</div>\n<p>其中 b 为批大小、s 为原序列长度、h 为隐藏维。举例：一个 1024×1024 分辨率、原潜空间序列长度数千的 DiT，在 r=4 时序列长度降到原来的四分之一，TP=8 组内每层 All-Reduce 的激活字节数相应降到约四分之一；若该层原本是通信主导，则单步延迟中通信占比明显下滑，反之若权重加载主导，收益被稀释。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-34\">三十四 · EP 与 All-to-All：压缩改变的是专家负载而非链路</h3>\n<p>若 DiT 主干采用专家混合（EP）结构，压缩潜空间缩短的是 token 序列，而 All-to-All 的通信量正比于 token 数 × 每 token 选中的专家数 × 隐藏维。序列缩短直接减少需要被路由的 token 数，因此 EP 组内 All-to-All 的字节数按 1/r 下降，但每个专家仍要处理固定比例的 token，专家并行度不变时单专家负载下降，可能出现专家利用率不足——此时应下调 EP 度数或增大批大小把 token 补回来，否则 All-to-All 虽便宜但计算单元空转。NVLink 5 与 NVSwitch 提供的是机柜内全互联带宽，All-to-All 的瓶颈通常不在链路本身，而在路由不均衡导致的尾部等待：少数热门专家收到的 token 数远超均值，其所在 GPU 成为拖尾，其他卡在 All-to-All 完成前空等。压缩潜空间不改变这种不均衡的比例结构，只等比缩小绝对量，所以负载均衡策略（容量因子、token 丢弃或复制专家）仍需保留。系统代价上，EP 的显存由专家权重主导，压缩不减少专家参数，故 EP 度数不能因通信变便宜而下调过多，否则单卡专家权重越界。</p>\n<ul>\n<li>机制：token 路由 → 按专家分组打包 → All-to-All 交换 → 专家计算 → All-to-All 回传。</li>\n<li>公式思路：单卡 All-to-All 发送量 ≈ (总 token 数 / EP 度数) × top-k × h × 字节数，压缩使总 token 数按 1/r 下降。</li>\n<li>代价：链路带宽充裕时，尾部等待由最热专家决定，压缩只缩短平均等待不缩短最坏等待。</li>\n<li>例子：同一批内若某专家承接了 30% 的 token，压缩后该比例不变，该卡仍是关键路径。</li>\n</ul>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-35\">三十五 · PP 与 DP：流水气泡与副本冗余的重新定价</h3>\n<p>流水并行（PP）的代价是气泡：micro-batch 数与流水级数的比值决定空转比例，而压缩潜空间缩短了每级前向时间，气泡的绝对时长随之缩短，但气泡占比由调度结构决定，不因压缩自动改善。真正变化的是 PP 级间点对点传输的激活字节数按 1/r 下降，使级间链路不再是瓶颈，于是可以把更多 micro-batch 塞进流水以填满气泡，代价是显存中同时驻留的激活副本增多——压缩后单份激活变小，正好抵消。数据并行（DP）在推理侧表现为副本冗余：每张卡持完整权重、各自处理不同请求。压缩潜空间降低的是每副本的激活显存与每步计算时间，权重显存不变，因此 DP 副本数受权重显存约束而非激活约束；当压缩比很高时，单副本激活显存趋近于零，DP 的瓶颈彻底转为权重常驻与负载均衡。系统代价上，DP 不产生集合通信（除负载均衡时的请求重分配），但副本越多、权重总显存越大，Blackwell 单卡容量固定时 DP 度数上限由模型参数量除以单卡可用显存决定，压缩比对此无贡献。工程上应把压缩比带来的显存余量优先用于增大批大小而非增大 DP 度数，因为批大小摊薄的是每步固定开销，DP 只增加并行请求数。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-36\">三十六 · NVLink 5、NVSwitch 与 NIXL：谁在什么时候成为瓶颈</h3>\n<p>Blackwell NVL72 机柜内通过 NVSwitch 做全互联，NVLink 5 提供的是卡间高带宽低延迟通路，使 TP 与 EP 的集合通信在机柜内不构成硬瓶颈；真正的瓶颈出现在跨机柜或跨节点时，此时链路退化为普通网络，All-Reduce 与 All-to-All 的带宽骤降，通信时间可能超过计算时间。DC-Gen 的压缩潜空间在这里的作用是降低跨节点传输的激活字节数：分离式预填/解码（PD 分离）架构中，预填节点把压缩潜变量传给解码节点，传输量按 1/r 下降，使跨节点传输窗口缩短；NIXL 作为点对点传输层，负责在节点间搬运这些潜变量与 KV 式缓存，其吞吐取决于消息大小与并发连接数——压缩后单条消息变小，若并发不变则总吞吐需求下降，但小消息的协议开销占比上升，需要合并传输或增大批以维持链路效率。判断通信是否成为瓶颈的实用准则是：比较单步计算时间 T_comp 与集合通信时间 T_comm，当 T_comm/T_comp 超过约一个可接受阈值（由 SLO 的每步延迟预算反推）时，应优先降并行度数或改用压缩比更高的档位，而不是加卡。</p>\n<table class=\"mini\"><thead><tr><th>并行维度</th><th>通信形态</th><th>压缩比 r 的影响</th><th>不随 r 缩小的部分</th></tr></thead><tbody><tr><td>TP</td><td>每层 All-Reduce</td><td>激活字节按 1/r 降</td><td>权重分片显存</td></tr><tr><td>EP</td><td>All-to-All 路由</td><td>token 数按 1/r 降</td><td>专家权重、路由不均衡</td></tr><tr><td>PP</td><td>级间点对点</td><td>激活字节按 1/r 降</td><td>气泡占比、级数</td></tr><tr><td>DP</td><td>无集合通信</td><td>激活显存按 1/r 降</td><td>权重副本常驻</td></tr></tbody></table>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-37\">三十七 · 通信瓶颈的判定与压缩比的联动标定</h3>\n<p>把压缩比当成并行拓扑的自由度，需要一个可执行的标定流程：固定批大小与分辨率桶，逐档提高压缩比，记录每步的 T_comp 与 T_comm，画出两者随 r 的曲线；当 T_comm 已降到 T_comp 的很小比例时，继续提高 r 只带来质量损失而无通信收益，此时应停止加深压缩，转而把省下的显存用于增大批或提高 TP 度数以外的其他杠杆。反之若 T_comm 仍占主导，说明瓶颈在权重加载或跨节点链路，压缩潜空间无法解决，需要检查是否误用了跨机柜的 TP 分组。低精度存放（FP8/NVFP4）与压缩误差叠加会同时降低传输字节数与数值保真度，二者对质量的影响不可分离标定，部署时应先固定精度再扫压缩比，或反之，避免两个旋钮同时动导致归因困难。监控侧应把每步的通信等待时间、All-to-All 尾部延迟、跨节点传输吞吐与压缩比一起记录，作为容量规划输入；当队列尾延迟逼近 SLO 时，优先降批大小或降精度，而不是盲目加并行度数——加度数会增加同步点，在通信已便宜时反而抬高固定开销。</p>\n<ul>\n<li>机制：以 T_comm/T_comp 比值作为是否继续加深压缩或调整拓扑的判据。</li>\n<li>公式思路：端到端每步延迟 ≈ T_comp(r) + T_comm(r, 拓扑) + T_固定开销，压缩只作用于前两项中的激活相关部分。</li>\n<li>代价：压缩比提高带来重建误差累积，通信收益递减后继续压缩是净损失。</li>\n<li>例子：同一 NVL72 机柜内 TP=8 的 DiT，压缩后 All-Reduce 字节降四倍，若单步仍被权重加载主导，则加卡无益，应改用更大批摊薄权重读取。</li>\n</ul>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-38\">三十八 · 压缩潜空间下的并行拓扑：切分维度如何被压缩比改写</h3>\n<p>DC-Gen 的压缩潜空间会直接改写并行切分的成本结构。原始潜空间下，DiT 的注意力序列长度与通道维度决定了张量并行（TP）的切分粒度：TP 沿权重矩阵的隐藏维切分，每层需在注意力输出与 MLP 下投影处插入 All-Reduce，通信量与激活张量的隐藏维成正比。压缩后隐藏维与序列长度同步下降，单次 All-Reduce 的消息体积随之缩小，TP 的有效扩展比在更小的域内即可饱和——这意味着在 Blackwell 单机 NVLink 5 域内，压缩比越高，可用的 TP 度数越容易落在通信可被计算掩盖的区间。但代价转移到了专家并行（EP）与数据并行（DP）：若压缩编码器与解码器按 DP 副本部署，每张卡都要独立承担编解码前向，压缩比降低了解码输入规模却未降低副本数，DP 的显存冗余反而成为主导项。工程判断是：压缩比提高后应优先收缩 TP 度数、把释放出的显存让给更大的批或更长的 KV 式中间缓存，而不是无脑加并行度。</p>\n<p>通信何时成为瓶颈，取决于每步计算时间与集合通信时间的比值。设单步 DiT 前向的计算量为 $C$、单卡有效算力为 $F$、单次 All-Reduce 消息量为 $M$、NVLink 5 单向带宽为 $B$，则单步时间近似为</p>\n<div class=\"formula\">$$T_{\\text{step}} \\approx \\frac{C}{F} + \\frac{2\\,(N-1)}{N}\\cdot\\frac{M}{B}$$</div>\n<p>其中 $N$ 为 TP 度数。压缩潜空间使 $C$ 与 $M$ 同比例下降，但 $M/B$ 项不会因压缩而消失——只要 TP 仍跨 NVLink 域，每步的 All-Reduce 就是固定税。当压缩比把 $C/F$ 压到与 $M/B$ 同量级时，通信占比越过临界点，继续加深压缩不再带来端到端收益，反而因每步固定通信开销摊薄变差。此时应把 TP 收敛到单 NVSwitch 域内、用 PP 或 EP 承担跨节点扩展，或直接把压缩潜变量以 FP8/NVFP4 存放以进一步压缩消息体积——但低精度与压缩误差叠加后的质量边界论文未给出，需逐档标定。</p>\n<table class=\"mini\"><thead><tr><th>切分维度</th><th>压缩后的主要影响</th><th>通信形态</th><th>失效条件</th></tr></thead><tbody><tr><td>TP</td><td>隐藏维与序列长度缩小，单次 All-Reduce 消息量下降</td><td>每层 All-Reduce，NVLink 5/NVSwitch</td><td>压缩比过深使计算时间逼近通信时间，扩展比饱和</td></tr><tr><td>EP</td><td>压缩不改变专家数，All-to-All 消息量由路由决定</td><td>All-to-All，跨 NVLink 域</td><td>批内路由不均导致 All-to-All 尾部拖长</td></tr><tr><td>PP</td><td>每步流水气泡占比随单步时间缩短而上升</td><td>点对点激活传递</td><td>步数多、单步短时气泡无法被填满</td></tr><tr><td>DP</td><td>编解码器副本显存冗余不随压缩比下降</td><td>梯度/参数同步（推理侧通常无）</td><td>副本数过多挤占压缩潜变量与批的显存预算</td></tr></tbody></table>\n<p>NIXL 传输在分离式预填/解码或编解码器与采样器分置的拓扑里承担潜变量搬运。压缩潜空间的直接好处是单次传输的有效载荷变小：编码器输出的低维张量经 NIXL 从预填节点送到采样节点，消息体积随压缩比下降，传输时间在端到端尾延迟中的占比被压缩。但这里有一个易被忽略的失效条件——解码器一次性还原像素，其输入虽小、输出却是全分辨率图像，若解码节点与采样节点分离，像素级输出的回传带宽并不因压缩而下降，反而可能成为新的尾延迟瓶颈。因此压缩比作为容量规划自由度时，必须同时标定三处峰值：采样节点上压缩潜变量与中间缓存的显存峰值、NIXL 链路上潜变量与像素回传的带宽占用、解码节点上 VAE 还原的瞬时显存。只测单请求延迟而不测批调度下的显存峰值，压缩潜变量与低精度存放叠加后峰值越界的风险最高；并发上升时应优先降批大小或降精度，而非继续加深压缩。</p>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-39\">三十九 · 精度塌陷：压缩误差与低精度叠加的失效链</h3>\n<p>DC-Gen 的精度风险不在单点，而在一条叠加链上：压缩编码器把原始潜变量压到低维，重建项系数 λ 决定保真度下限；采样器在这个压缩空间里跑数十步去噪，每一步的预测误差都会沿步数累积；最后压缩解码器一次性还原像素，把前面所有步的误差一次性放大到可见域。这条链上任何一环的余量不足，表现都不是“稍微糊一点”，而是结构性塌陷——高频纹理先丢，然后是边缘振铃，最后是语义漂移。</p>\n<p>诊断的关键是把误差拆成可观测的量。对单请求，可以在采样轨迹上记录相邻步预测的余弦相似度与潜变量范数增长率：压缩空间若与原模型训练分布偏移，范数会在中后段异常抬升，余弦相似度掉到低位，这是采样不稳定的前置信号。对批，则要记录同一批内不同请求的最终潜变量统计量离散度，离散度异常说明批内某些样本已经跑飞，而调度器仍在按正常延迟预算排队。</p>\n<div class=\"formula\">$$\\text{drift}_t=\\frac{\\|\\hat{z}_{t}-\\hat{z}_{t-1}\\|_2}{\\|\\hat{z}_{t-1}\\|_2},\\quad \\text{flag if } \\text{drift}_t&gt;\\tau_{\\text{drift}}\\ \\text{for } k \\text{ consecutive steps}$$</div>\n<p>代价层面：精度塌陷不会直接打爆显存，但会让重试率上升。一次失败请求若被上层重放，等于把整条采样链路再跑一遍，尾延迟被成倍拉长；在按分辨率与步数分桶的批里，一个坏样本还会拖住同批其他请求的完成时刻。具体例子：某档压缩比下，λ 偏小导致重建项权重不足，解码器对细密纹理的还原能力下降，采样本身在压缩空间内是“自洽”的，但解码后像素域出现明显块状伪影——监控侧若只看潜空间指标会判定正常，必须把解码后的像素质量指标纳入同一请求的记录。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-40\">四十 · OOM：峰值显存的三处叠加点</h3>\n<p>压缩潜空间降低了每步张量规模，但 OOM 往往不是被采样主干打爆的，而是被三处叠加点打爆：其一，压缩潜变量以 FP8 或 NVFP4 存放后，若适配层或某些算子仍以高精度副本参与计算，会出现同一张量多份驻留；其二，批调度把同桶请求合并后，批内张量按批大小线性增长，而压缩比带来的余量被误当成“可以无限加批”的免费空间；其三，VAE 解码阶段的一次性像素还原是峰值显存的高点，解码输入规模虽随压缩比下降，但输出像素张量与中间特征图并不随压缩比缩小。</p>\n<p>定位手段是给显存峰值打三段时间戳：编码后、采样每步、解码前与解码中。若峰值出现在解码中，说明压缩比的红利没有传导到解码器内部实现；若峰值随批大小线性抬升且斜率与压缩比无关，说明批内存在未压缩的高精度副本。工程判断上，压缩比是容量规划的自由度，但它的显存收益必须逐档实测，不能从维度比例直接推算。</p>\n<table class=\"mini\"><thead><tr><th>叠加点</th><th>典型诱因</th><th>观测信号</th><th>处置</th></tr></thead><tbody><tr><td>精度副本</td><td>FP8/NVFP4 潜变量与高精度适配层并存</td><td>单请求显存随批不变但基线上移</td><td>统一存放精度，收敛副本</td></tr><tr><td>批线性增长</td><td>压缩余量被当作加批空间</td><td>峰值随批大小线性、斜率偏大</td><td>降批大小或降精度</td></tr><tr><td>解码峰值</td><td>像素输出与中间特征不随压缩比缩小</td><td>峰值集中在解码窗口</td><td>解码分块或串行化解码</td></tr></tbody></table>\n<p>具体例子：并发上升时调度器按既定策略加批，压缩潜变量已转 FP8，但解码器仍按原分辨率一次性还原，结果显存峰值越界触发 OOM killer，表现为整批请求同时失败而非单请求降级——这种“批级联失败”是最难回滚的形态，因为失败点不在请求粒度上。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-41\">四十一 · 批抖动与尾延迟：分桶边界上的排队失稳</h3>\n<p>按分辨率与采样步数分桶合并请求，本意是摊薄 DiT 前向开销，但压缩比引入了一个新的抖动源：不同压缩档位对应不同的每步延迟与解码开销，若调度器仍按未压缩时代的桶边界与批窗口排布，桶内请求的完成时刻会离散化。更隐蔽的是步数分布的长尾——少数高步数请求落进低步数桶，会把整批的完成时间拖到窗口之外，形成周期性抖动。</p>\n<p>诊断批抖动要看两个量：批完成时刻的方差，以及桶内请求步数的分布偏度。方差抬升而单请求延迟正常，说明问题在批组装而非单请求执行；偏度大则说明桶边界需要按步数重新切分。尾延迟的构成也要拆开：采样段尾延迟与解码段尾延迟的占比会随压缩比改变，压缩越深，解码在端到端中的占比越突出，此时优化采样步数对尾延迟的边际收益下降。</p>\n<div class=\"formula\">$$T_{\\text{e2e}}=T_{\\text{enc}}+\\sum_{t=1}^{S}T_{\\text{step}}(t)+T_{\\text{dec}},\\quad \\text{tail}=\\max_{\\text{batch}}\\big(T_{\\text{e2e}}\\big)-\\text{median}\\big(T_{\\text{e2e}}\\big)$$</div>\n<p>代价上，批抖动的直接后果是 SLO 违约集中在窗口末尾，容量规划若按中位延迟估算会系统性低估所需副本数。具体例子：某桶内混入步数远高于桶均值的请求，采样段被拉长，同批低步数请求本可早完成却被绑定等待，尾延迟抬升；处置不是加机器，而是把桶按步数细分并把高步数请求单独成批，牺牲一点批效率换尾延迟稳定。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-42\">四十二 · 静默降级：没有报错的质量滑坡</h3>\n<p>最危险的一类失败不产生任何错误码：压缩比在容量压力下被自动调深，或潜变量精度从 FP8 降到 NVFP4，链路照常返回图像，但质量已经跨过可接受边界。静默降级的根源是质量指标没有和压缩档位、精度档位绑定成同一条监控记录——运维看到的是延迟与显存正常，用户看到的是细节丢失。</p>\n<p>监控设计上，必须把压缩比、潜变量存放精度、λ 档位作为请求级标签写入指标，并对每个档位维护独立的质量基线。质量基线不能只靠离线标定，要在服务侧抽样做轻量代理指标：解码后图像的高频能量占比、潜变量轨迹的 drift 统计、以及同档位历史样本的分布距离。任一代理指标偏离基线超过阈值即触发告警，而不是等到用户投诉。</p>\n<ul>\n<li>档位标签化：压缩比、精度、λ 三者组合成配置指纹，指标按指纹聚合，避免跨档位平均掩盖劣化。</li>\n<li>抽样代理指标：高频能量、drift 统计、分布距离，成本低、可在线跑。</li>\n<li>降级审计：任何自动降档动作必须留痕，记录触发原因与恢复条件。</li>\n</ul>\n<p>代价判断：静默降级的“代价”不是算力而是信任与重试。质量滑坡若未被发现，用户侧重试或换服务会把负载推高，反过来又触发更深的压缩档位，形成正反馈。具体例子：并发高峰时自动把潜变量转 NVFP4，延迟与显存指标全部达标，但低精度与压缩误差叠加后的质量边界论文未给出，服务侧若无代理指标，劣化会持续整个高峰窗口而无人察觉。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-43\">四十三 · 定位与回滚：把配置指纹做成可回退单元</h3>\n<p>定位的顺序应当是自下而上：先看单请求的 drift 与解码后代理指标，判断是精度塌陷还是解码问题；再看批级显存峰值时间戳，区分 OOM 是批组装还是解码峰值；最后看桶级完成时刻方差，判断抖动来自桶边界还是步数长尾。三步都指向同一个工程要求：每一次配置变更都必须是一个可独立回退的单元。</p>\n<p>回滚不是简单地把压缩比调回去。压缩比、λ、潜变量精度、批大小、桶边界是耦合的：把压缩比调浅会抬高每步张量规模与显存峰值，若批大小不同步下调，OOM 会立刻复现；把精度调回高精度会抬升带宽占用，若解码分块策略不变，解码峰值仍在。因此回滚单元应是一组配置指纹的整体切换，而不是单旋钮微调。灰度上，新指纹先在小比例流量上跑，用代理指标与尾延迟双门槛决定是否放量；任一门槛不达标即整体回退到上一指纹。</p>\n<div class=\"formula\">$$\\text{rollback}=\\arg\\min_{\\text{fp}\\in\\text{Fingerprints}}\\Big(\\mathbb{1}[\\text{tail}&gt;\\text{SLO}]+\\mathbb{1}[\\text{proxy}&lt;\\text{baseline}]\\Big)$$</div>\n<p>具体机制上，配置指纹要包含压缩比档位、λ、潜变量存放精度、批大小上限、桶边界版本，以及解码分块参数；每个指纹对应一套标定过的显存峰值与尾延迟预算。监控侧按指纹聚合指标，告警按指纹触发，回滚按指纹执行。代价是标定工作量随指纹组合数增长，工程上应限制同时生效的指纹数量，把压缩比与精度的组合收敛到少数几档，避免组合爆炸让回滚失去可操作性。</p>\n<p>工程判断落在最后一步：DC-Gen 把加速杠杆从“加步数、加批”转向“压潜空间”，这意味着失败模式的重心也从算力瓶颈转向质量边界与显存叠加点。论文未给出失败阈值与质量下限，部署侧唯一可靠的做法是把每个压缩档位当作独立产品档位来标定——档位内的显存峰值、尾延迟、代理质量指标三者必须同时达标才允许上线，任一指标失守即整档回退，而不是在档位内部做局部修补。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-44\">四十四 · 压缩比越界后的静默降级与回滚判据</h3>\n<p>DC-Gen 最危险的失效不是崩溃，而是<b>静默降级</b>：压缩编码器把分布外的输入映射到压缩潜空间后，主干仍能正常出图，但细节纹理与结构一致性已经劣化，而服务侧所有延迟与显存指标全部“健康”。根因在于主干冻结、只训编解码器，压缩空间与原模型训练分布存在偏移，极端压缩比下重建误差沿采样步累积。诊断上不能只看端到端成功率，必须在链路中埋两个探针：一是解码前的潜变量重建残差 <span class=\"formula\">$$r=\\|\\mathcal{D}(\\mathcal{E}(x))-x\\|_2/\\|x\\|_2$$</span> 按桶统计分位数；二是固定种子参考集上的采样质量指标，按压缩比档位分别留存基线。当某档位的 <i>r</i> 高分位或质量指标相对基线漂移超过预设阈值，即判定该压缩比档位失效，自动把该桶请求路由回未压缩潜空间路径——这是唯一可靠的回滚方式，因为主干未重训，无法靠微调主干补偿。</p>\n<p>第二类失效是显存峰值越界引发的 OOM 与批抖动。压缩潜变量以 FP8/NVFP4 存放确实压低每步带宽，但压缩误差与低精度误差叠加后的质量边界论文未给出，而解码器一次性还原像素时的峰值显存并不随压缩比线性下降。工程上应把批大小与精度档位做成联动约束：<table class=\"mini\"><thead><tr><th>触发条件</th><th>动作</th><th>代价</th></tr></thead><tbody><tr><td>桶内显存峰值逼近预算</td><td>降批大小</td><td>吞吐下降、尾延迟抬升</td></tr><tr><td>批抖动（批大小频繁重排）</td><td>锁定桶窗口，拒绝跨桶合并</td><td>小批请求排队变长</td></tr><tr><td>解码段占端到端尾延迟比例上升</td><td>降压缩比档位或拆解码批</td><td>DiT 每步张量规模回升</td></tr></tbody></table>批抖动的本质是分桶键（分辨率×步数×压缩比）维度过细，调度器在并发波动下反复拆合批，DiT 前向的摊薄效应消失，尾延迟被小批请求拖长。</p>\n<p>定位顺序应是自尾向头：先看端到端尾延迟分解中解码段与 DiT 每步延迟的占比变化，再对照压缩比档位与精度档位的监控曲线，最后落到具体桶的 <i>r</i> 分位数与质量探针。容量规划时把压缩比当作独立自由度而非免费旋钮，每档压缩比都必须标定对应的显存峰值、每步延迟与质量下限，未标定的档位不得进入生产路由表。</p>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-45\">四十五 · 论文口径的空缺与自建标定的必要性</h3>\n<p>DC-Gen 的材料里没有给出任何可复现的基准数字：加速比、压缩比取值、重建指标、硬件档位、并行拓扑、量化配置全部缺席。这不是叙述上的省略，而是口径层面的空缺——它决定了这篇论文的结果不能被直接引用为“在某卡上快了多少倍”。对工程读者而言，正确的读法是把它当成一个<strong>结构性主张</strong>而非性能主张：主张的内容是“压缩潜变量维度会同步缩小 DiT 每步张量规模与 VAE 解码输入”，而“缩小多少、换来多少延迟”必须由部署方自己在 Blackwell 档位上标定。因此本部分讨论的不是复述论文数字，而是建立一套可迁移的测量框架：哪些量必须测、怎么测、哪些跨配置比较在方法上就不成立。</p>\n<p>标定的最小闭环是三条曲线：压缩比—每步延迟、压缩比—显存峰值、压缩比—质量指标。三者必须同批采集，因为压缩比同时作用于计算量与保真度，单独测任何一条都会给出误导性的单调结论。工程上把压缩比记为 <em>r</em> = dim(z_orig)/dim(z)，则 DiT 注意力的序列长度与线性层张量规模大致按 <em>r</em> 收缩，但 VAE 解码的输入规模收缩比例与 <em>r</em> 不必一致（解码器结构决定了通道与空间的映射方式），所以端到端延迟的改善不是简单的 1/<em>r</em> 关系。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-46\">四十六 · 硬件档位与 batch／并发的交叉变量</h3>\n<p>Blackwell 的 SM100/SM103 档位（B200/B300、GB200/GB300 NVL72）在显存容量、NVFP4/FP8 张量核心吞吐、NVLink 5 域规模上并不等价，而 DC-Gen 的收益恰恰与这些量耦合：压缩潜变量能以 FP8 或 NVFP4 存放，意味着显存带宽占用与张量核心吞吐同时被压缩比和精度两个旋钮调制。若在 B200 单机上测得一组数，搬到 GB200 NVL72 的机架级部署上，通信域变大、批调度窗口变宽，同一压缩比对应的尾延迟会变——因为批内请求的分桶粒度与跨卡同步开销都变了。跨档位比较必须先固定“压缩比 × 精度 × 批大小 × 分桶策略”四元组，否则数字不可比。</p>\n<p>batch 与并发是两个必须分开记录的量。批大小决定单次 DiT 前向的算力摊薄程度，并发决定队列深度与显存驻留请求数。DC-Gen 的压缩潜变量让单请求驻留显存下降，于是同一显存预算下可容纳更高并发；但并发上升时若不同步下调批大小或精度，压缩潜变量与低精度存放叠加后的峰值显存仍可能越界——这是材料明确列出的失败模式。测量时应记录三元组 (batch, concurrency, peak_mem)，并给出越界边界，而不是只报一个“最大吞吐”。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-47\">四十七 · 指标定义：TTFT、TPOT 与扩散采样的错位</h3>\n<p>TTFT/TPOT 这套指标来自自回归解码，直接套到扩散采样上会产生语义错位。扩散请求的“首 token”对应的是首帧可用（首次可展示的中间结果或首步去噪完成），而“每 token 时间”对应的是每步去噪时间。DC-Gen 改变的是每步张量规模，因此它主要作用于 TPOT 一侧；而 VAE 解码是一次性开销，落在端到端尾延迟的末段，对 TTFT 的影响取决于服务是否采用流式中间结果。工程上应把端到端延迟拆成三段：编码（压缩编码器）、采样（N 步 × 每步延迟）、解码（压缩解码器）。压缩比提高时，采样段按步数线性受益，解码段一次性受益，编码段则可能因编码器本身的计算而略微增加——三段占比随压缩比移动，只看总延迟会掩盖这个结构变化。</p>\n<div class=\"formula\">$$T_{\\text{e2e}} \\approx T_{\\text{enc}}(r) + N \\cdot T_{\\text{step}}(r, \\text{prec}, B) + T_{\\text{dec}}(r)$$</div>\n<p>其中 <em>N</em> 是采样步数，<em>B</em> 是批大小，prec 是潜变量存放精度。这个式子说明：压缩比的收益在 <em>N</em> 较大时才显著，因为解码段只被摊薄一次；若某类请求步数很少（例如少步采样场景），压缩比带来的端到端改善会被编码段抵消一部分。容量规划时应按步数分桶分别拟合这条曲线，而不是全局取一个平均。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-48\">四十八 · 吞吐与功耗：两个容易被混用的口径</h3>\n<p>吞吐必须声明计量单位：请求/秒、图像/秒、还是像素/秒。扩散服务里三者不等价，因为分辨率分桶后单请求的计算量差异巨大。DC-Gen 的压缩比作用于潜空间维度，对高分辨率请求的相对收益更大（原始潜空间张量更大，压缩后绝对节省更多），因此混合分辨率负载下的“平均吞吐提升”高度依赖负载的分辨率分布——这是一个不可跨论文比较的量，除非同时给出分辨率直方图。功耗口径同理：Blackwell 档位的功耗墙与张量核心利用率相关，压缩潜变量降低带宽占用后，若算力利用率不升，功耗可能不降反升（单位时间做的有效工作变少而静态功耗不变），所以“省电”不能从“省带宽”直接推出。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>计量对象</th><th>受压缩比影响的路径</th><th>不可比情形</th></tr></thead><tbody><tr><td>TTFT</td><td>首帧可用时刻</td><td>编码段 + 首步去噪</td><td>流式与非流式服务混比</td></tr><tr><td>TPOT</td><td>每步去噪时间</td><td>DiT 张量规模 ∝ 1/r</td><td>步数不同、调度策略不同</td></tr><tr><td>吞吐</td><td>请求/图像/像素每秒</td><td>批摊薄 × 压缩收益</td><td>分辨率分布不同</td></tr><tr><td>显存峰值</td><td>单批驻留</td><td>潜变量 + 中间缓存 + 精度</td><td>并发与批大小不同</td></tr><tr><td>功耗</td><td>整卡/整机</td><td>带宽占用与算力利用率</td><td>利用率档位不同</td></tr></tbody></table>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-49\">四十九 · 哪些提升不可比：四类典型陷阱</h3>\n<ul>\n<li><strong>基线不同。</strong>DC-Gen 的基线是“未压缩潜空间的原始扩散/流匹配采样器”，但原始采样器本身可能已带 FP8/FP16 精度、不同步数调度。若对比方的基线是未量化的高精度版本，则压缩比与量化收益被混在一起，无法归因。</li>\n<li><strong>质量口径不同。</strong>材料只给出“重建指标与采样质量同时可接受”的定性表述，没有指标名。重建损失（像素级）与采样质量（分布级）不是同一件事：压缩比提高时重建误差累积，但采样质量可能因主干未重训的分布偏移而以不同速率退化。用重建指标替代生成质量做比较是口径错误。</li>\n<li><strong>精度叠加未分离。</strong>压缩潜变量以 FP8/NVFP4 存放是独立旋钮。若一方开了低精度、另一方没开，则吞吐差异同时包含压缩与量化两份贡献，且低精度与压缩误差叠加后的质量边界材料明确说“未给出”，这种比较在质量侧无法闭合。</li>\n<li><strong>批调度策略不同。</strong>按分辨率与步数分桶合并请求是 DC-Gen 链路的一部分。若对比方用固定批大小或不同分桶粒度，则显存峰值与尾延迟的差异来自调度而非压缩，属于系统性混淆。</li>\n</ul>\n<p>一个具体例子：假设部署方在 B200 上测得压缩比 r=4 时每步延迟下降，同时在 GB200 NVL72 上测得吞吐提升更明显。这两个数字不能拼成“压缩比在机架级更有效”的结论，因为后者混入了更大通信域下的批调度窗口变化与跨卡同步开销。正确做法是在同一拓扑内做压缩比的单变量扫描，把拓扑作为外层因子单独报告。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-50\">五十 · 可复现的标定流程与工程判断</h3>\n<p>可操作的标定流程是：固定分辨率直方图与步数分布，先在单卡上做压缩比扫描（r 取若干档），每档记录三段延迟、显存峰值、重建指标与采样质量指标；再固定最优 r，做精度扫描（FP16/FP8/NVFP4）与批大小扫描，记录越界边界；最后把拓扑从单卡换到 NVL72，重跑同一网格，观察哪些量随拓扑漂移。监控侧持续记录每步延迟、显存峰值与压缩比对应的质量指标，用于 SLO 与容量规划——材料明确要求这一点，说明压缩比被设计为运行时自由度而非一次性编译期常量。</p>\n<p>工程判断落在压缩比的选择准则上：不应追求“最大可压缩比”，而应选在质量指标尚未出现可测退化、且显存峰值在目标并发下留有余量的那一档。由于主干未重训，压缩空间与原模型训练分布的偏移随压缩比加深而累积，极端压缩下的细节丢失阈值材料未量化，因此每一档都必须实测而非外推。压缩比、精度、批大小三者构成一个三维容量曲面，SLO 规划是在该曲面上找满足尾延迟约束且质量可接受的点，而不是引用论文里的单一加速比。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-51\">五十一 · 压缩比不是免费旋钮：口径边界与失效条件</h3>\n<p>把 DC-Gen 放进容量规划时，第一个要拆掉的幻觉是“压缩比即加速比”。压缩比 r 只决定张量形状，不决定端到端收益。设原始潜空间序列长度为 N、通道为 C，压缩后为 N/r_s 与 C/r_c，则 DiT 每步注意力矩阵的元素数按 (N/r_s)² 缩，线性层按 (N/r_s)(C/r_c) 缩，而 VAE 解码输入按 1/(r_s·r_c) 缩。但端到端每请求时间近似为 T ≈ S·t_dit(r) + t_dec(r) + t_enc，其中 S 是采样步数、t_enc 是压缩编码器的一次性前向。当 S 较大时 t_enc 可摊薄；当 S 较小或分辨率较低时，编码器开销会吃掉压缩收益，这是该方案在小步数、低分辨率桶上的天然失效区。口径上必须报告“含编码器”的端到端延迟，只报 DiT 每步延迟会系统性高估收益。</p>\n<p>第二个口径问题是质量指标与压缩比不可跨档比较。λ 控制重建项权重，压缩比与 λ 共同决定重建误差，而重建误差在采样链路里会被逐步放大：压缩空间与原模型训练分布的偏移使 ε_θ 的预测落在分布外区域，极端压缩下细节丢失与采样不稳定同时出现，且论文未给出失败阈值。因此任何“压缩到 X 倍仍可用”的结论都必须绑定 λ、分辨率桶与步数桶三要素，脱离这三者的加速数字不可比。工程判断是：把压缩比当作分桶级配置而非全局常量，按分辨率与步数分桶各自标定，宁可在高分辨率桶用较浅压缩保质量，在低分辨率桶用较深压缩换吞吐。</p>\n<p>第三个口径是显存与精度叠加。压缩潜变量以 FP8 或 NVFP4 存放可降低每步带宽，但压缩误差与量化误差是相乘而非相加的关系，低精度下的质量边界论文未给。容量规划应把“压缩比 × 精度档”作为二维标定表，逐格测显存峰值与尾延迟，而不是只测单请求延迟——批调度合并同桶请求后，压缩潜变量与中间缓存的峰值显存在并发上升时可能越界，此时优先降批大小而非继续加深压缩。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>必须绑定</th><th>不可比的情形</th></tr></thead><tbody><tr><td>端到端延迟</td><td>含编码器 + 解码器 + S 步</td><td>只报 DiT 每步</td></tr><tr><td>质量指标</td><td>压缩比 + λ + 分辨率桶</td><td>跨 λ 或跨桶比较</td></tr><tr><td>显存峰值</td><td>批大小 + 精度档</td><td>单请求空载测量</td></tr></tbody></table>\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-52\">五十二 · 迁移到非图像模态：压缩器要重训，主干未必能冻</h3>\n<p>DC-Gen 的后训练契约是“冻结主干、只训编解码器”，这条契约成立有一个隐含前提：压缩空间与主干训练时见到的潜空间在统计上足够接近，主干在压缩潜变量上仍能给出有意义的噪声／速度预测。图像与视频扩散里，这个前提相对容易满足，因为原始潜空间本身就是 VAE 编码器的输出，本身带有学习得到的低维结构，再压一层只是把冗余进一步挤掉。迁到音频、3D 资产、分子构象或时序信号时，情况不同：这些模态的“原始潜空间”往往不是由同族自编码器产生，主干的输入分布与压缩器输出分布之间存在系统性偏移，冻结主干就会把偏移直接暴露在采样轨迹上。</p>\n<p>工程判断是：跨模态迁移时，压缩器的训练目标必须显式包含“让主干在压缩空间上可采样”的项，而不只是像素／波形重建。公式上，重建项 λ 之外应引入一项让冻结主干的去噪预测在压缩潜变量上保持自洽的约束，例如在压缩空间上跑短步数采样并把主干预测与原始空间预测做对齐：</p>\n<div class=\"formula\">$$\\mathcal{L}_{\\text{port}}=\\mathcal{L}_{\\text{DC-Gen}}+\\mu\\,\\mathbb{E}_{t}\\big\\|\\epsilon_\\theta(z_t^{\\text{cmp}},t)-\\epsilon_\\theta(z_t^{\\text{orig}},t)\\big\\|_2^2$$</div>\n<p>代价落在训练侧而非推理侧：多一项主干前向意味着后训练显存与时间上升，但推理链路不变。若不做这一步，迁移后常见的现象是低步数下结构先崩、高步数下细节抖动，表现为采样不稳定而不是单纯的质量下降——这与“压缩比过高”的失败模式不同，前者是分布偏移，后者是信息丢失，诊断时要分开看。视频模态还要多一层：时间维压缩会改变帧间注意力的感受野，压缩器若按单帧独立压缩，主干的时间建模会被削弱，需要把时间维一并纳入压缩器的感受野设计。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-53\">五十三 · 迁移到非 DiT 主干：注意力序列缩短的收益不再线性</h3>\n<p>DC-Gen 的加速账本主要记在“DiT 注意力序列长度与线性层张量规模同步缩小”上。这套账本对以全局自注意力为主干的结构最有效，因为注意力矩阵随序列长度平方增长，压缩潜空间的序列缩短直接砍掉二次项。迁到以卷积为主、或以局部窗口注意力为主、或采用线性注意力的主干时，二次项本就不占主导，压缩带来的每步计算下降会被一次项（通道投影、归一化、逐元素运算）稀释，端到端加速比显著低于注意力主导的模型。</p>\n<p>判断依据可以直接从代价结构推：设原始序列长度 N、压缩后 n，注意力主导时每步代价约正比于 N²d，压缩后为 n²d；若主干以深度卷积为主，每步代价约正比于 N·d·k²（k 为核宽），压缩只按 n/N 线性摊薄。因此迁移前应先做主干的算子画像，确认注意力在每步延迟中的占比，占比低于某一水平时，压缩潜空间的吞吐收益要让位给别的杠杆（低精度、批调度、步数蒸馏）。这一点与量化类方案的分工要分清：量化压的是每个元素的位宽，压缩潜空间压的是元素个数，两者在带宽账本上可叠加，但在计算账本上的主导项不同。</p>\n<table class=\"mini\"><thead><tr><th>主干形态</th><th>每步主导代价</th><th>压缩潜空间的收益</th><th>迁移风险</th></tr></thead><tbody><tr><td>全局自注意力 DiT</td><td>注意力矩阵 N²d</td><td>二次项同步下降，收益最大</td><td>低</td></tr><tr><td>窗口／局部注意力</td><td>窗口内 N·w²d</td><td>线性摊薄，收益中等</td><td>窗口划分需随压缩比重标</td></tr><tr><td>卷积为主干</td><td>N·d·k²</td><td>线性摊薄，收益有限</td><td>感受野与压缩率错配</td></tr><tr><td>线性注意力／SSM</td><td>N·d²</td><td>仅通道维收益</td><td>状态维与压缩维需对齐</td></tr></tbody></table>\n<p>具体例子：一个以 U-Net 卷积块为主、注意力只出现在低分辨率层的图像扩散模型，把潜空间压到四分之一序列长度后，注意力层延迟明显下降，但卷积层延迟几乎不变，端到端每步延迟的改善被卷积部分封顶。此时继续加深压缩比只会增加重建误差而不换来吞吐，工程上应停止加压缩、转向批合并与低精度存放。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-54\">五十四 · 与低精度叠加的边界：误差是相乘而非相加</h3>\n<p>Blackwell 档位允许把压缩潜变量以 FP8 或 NVFP4 存放，这条能力让压缩与量化在带宽账本上叠加：压缩比 r 降低元素个数，位宽 b 降低每元素字节数，每步潜变量读写带宽约正比于 dim(z)·b。但两条误差路径不是独立相加，而是相乘叠加：压缩带来的重建误差在低精度表示下会被进一步放大，因为低精度量化对已经偏离原分布的压缩表示更敏感，尾部分布更容易被截断。</p>\n<div class=\"formula\">$$\\text{每步带宽}\\propto \\dim(z)\\cdot b,\\qquad \\text{误差}_{\\text{总}}\\approx f(\\text{误差}_{\\text{压缩}},\\ \\text{误差}_{\\text{量化}})$$</div>\n<p>工程判断是：压缩比与位宽必须联合标定，不能各自扫到极限再拼。可行的做法是先固定位宽（例如先用 FP8 而非直接上 NVFP4），把压缩比扫到质量可接受的上界，再在该压缩比下试低一档位宽，观察质量指标是否越界；若越界则回退位宽而不是回退压缩比，因为回退压缩比会同时损失吞吐与显存收益，回退位宽只损失带宽收益。代价体现在显存峰值与尾延迟的耦合上：低精度存放降低带宽占用，但若压缩解码器需要在解码前把潜变量升精度，升精度那一步会引入一次额外的显存读写，压缩比越高、这次读写的相对占比越大，需要在解码器实现里避免全量升精度。</p>\n<p>具体例子：同一压缩比下，FP8 存放的潜变量在解码器入口做一次反量化再进卷积，若反量化写成独立 kernel，就会多一次全量读写；把反量化融进解码器第一个卷积的加载路径，这次读写消失，尾延迟中的解码占比下降。这类融合是迁移到新解码器结构时必须重做的工程活，不能假设原实现可平移。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-55\">五十五 · 规模上限：压缩比的天花板由解码器感受野与主干容量共同决定</h3>\n<p>压缩比不能无限加深，上限由两个因素夹住。其一是解码器的重建能力：压缩解码器要从低维表示还原像素，其感受野与容量必须覆盖被压掉的信息量，压缩越深，解码器需要的容量越大，而解码器容量本身受显存与解码延迟约束——解码是一次性的大张量还原，容量上去后解码峰值显存与时间会吃掉压缩在采样阶段省下的收益。其二是主干的表达能力：主干在压缩空间上做去噪，压缩空间的维度若低于主干有效建模所需的最小维度，主干无法在低维空间里区分不同语义方向，采样会退化为模式平均。</p>\n<p>因此存在一个吞吐拐点：压缩比从 1 加深到某一档位时，采样每步延迟与显存峰值单调下降，端到端吞吐上升；越过该档位后，解码器容量与解码延迟上升的速度超过采样阶段节省的速度，端到端吞吐反而回落，同时质量指标加速恶化。这个拐点无法从论文给定材料中读出，必须由部署方逐档标定，标定口径应同时记录每步延迟、解码延迟、显存峰值与质量指标，而不是只看采样阶段。</p>\n<ul>\n<li>标定顺序：固定批大小与位宽，扫压缩比，记录端到端尾延迟而非仅采样延迟。</li>\n<li>拐点判据：解码延迟占端到端延迟的比例随压缩比上升而上升，且上升斜率超过采样延迟下降斜率时，即为拐点。</li>\n<li>规模上限的另一维是批：压缩潜变量变小后单请求显存下降，批可以开大，但解码阶段是一次性大张量，批内解码并发会推高解码峰值显存，批大小与压缩比需要联合定容。</li>\n</ul>\n<p>具体例子：把压缩比推到使潜变量序列长度降到主干的注意力窗口以下时，注意力机制退化为近似全局池化，主干失去空间选择性，生成结果的布局多样性下降——这不是重建误差问题，而是主干容量问题，继续调 λ 无法修复，只能回退压缩比或对主干做轻量微调。</p>\n\n<h3 id=\"paper-dc-gen-post-training-diffusion-accel-2025-sec-56\">五十六 · 不适用的场景与工程判断</h3>\n<p>有三类场景应明确不套用这套方案。第一类是单步或少步生成模型：若采样步数已被压到个位数，采样阶段的每步张量规模不再是瓶颈，压缩潜空间省下的采样开销占比很小，而压缩器与解码器引入的额外前向与重建误差却实打实存在，收益为负。第二类是对像素级保真度有硬约束的任务，例如需要精确文字渲染、精确几何边缘或医学影像细节的场景：压缩重建误差在极端压缩下表现为细节丢失，而这类任务的验收口径恰恰卡在细节上，λ 调高会牺牲压缩比、调低会牺牲保真度，两端都不满足。第三类是主干与压缩器分布严重不匹配且不允许任何主干微调的部署：冻结主干加纯编解码器后训练在跨模态时容易采样不稳定，若业务不允许轻量微调，应放弃该路线而不是靠调 λ 硬扛。</p>\n<p>反过来，最适合迁移的场景画像清晰：主干以全局注意力为主、采样步数在数十步量级、显存峰值是主要容量约束、业务质量口径允许一定重建误差、且部署方有能力做逐档标定。在这些条件下，压缩潜空间是一个与低精度存放正交的容量杠杆，能在不重训主干的前提下把显存峰值与每步带宽同时压下来。</p>\n<p>最后落在工程判断上：迁移这套方案时，第一件要做的事不是调压缩比，而是量出目标模型每步延迟里注意力、线性层、解码三段的占比，以及显存峰值里潜变量、中间缓存、解码输入三块的占比。若注意力与潜变量两块占比高，压缩潜空间值得投入；若解码占比高，应先优化解码器实现与融合反量化；若卷积或一次项占比高，压缩比再深也换不来吞吐，应把预算投向批调度与低精度算子。压缩比、λ、位宽、批大小这四个旋钮必须在同一张标定表上联合扫描，任何单旋钮的极限值都不是部署参数。</p>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">DC-Gen: Post-Training </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Diffusion Acceler…</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · DC-Gen: Post-Training D… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>沿用原扩散模型的图像训练分布，具体数据集未给出</td></tr><tr><td>基线</td><td>未压缩潜空间的原始扩散／流匹配采样器</td></tr><tr><td>主要结果</td><td>论文主张在后训练阶段实现深度压缩潜空间并加速采样，压缩后 DiT 每步张量…</td></tr><tr><td>消融</td><td>材料未给出消融实验细节，仅可推断压缩比与重建损失权重 λ 是主要可调因素，…</td></tr><tr><td>局限</td><td>压缩比提高会带来重建误差累积，采样质量与压缩比之间存在权衡；后训练只适配编…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-dc-gen-post-training-diffusion-accel-2025 · 共 9 个片段</p>\n";break;}}})();
